#include <iostream>
#include <unordered_map>
#include <memory>
#include <chrono>
#include <optional>
#include <mutex>

template <typename K, typename V>
class LRUCacheWithTTL {
private:
    struct Node {
        K key;
        V value;
        std::chrono::steady_clock::time_point expiryTime;
        bool hasExpiry;
        std::shared_ptr<Node> prev;
        std::shared_ptr<Node> next;

        Node(K k, V v, bool hasTtl, std::chrono::steady_clock::time_point exp)
            : key(k), value(v), hasExpiry(hasTtl), expiryTime(exp), prev(nullptr), next(nullptr) {}

        bool isExpired() const {
            if (!hasExpiry) return false;
            return std::chrono::steady_clock::now() > expiryTime;
        }
    };

    size_t capacity;
    std::unordered_map<K, std::shared_ptr<Node>> cacheMap;
    std::shared_ptr<Node> head;
    std::shared_ptr<Node> tail;
    mutable std::mutex mtx;

    void removeNode(std::shared_ptr<Node> node) {
        if (!node) return;
        if (node->prev) node->prev->next = node->next;
        else head = node->next;

        if (node->next) node->next->prev = node->prev;
        else tail = node->prev;

        node->prev = nullptr;
        node->next = nullptr;
    }

    void addToHead(std::shared_ptr<Node> node) {
        node->next = head;
        node->prev = nullptr;
        if (head) head->prev = node;
        head = node;
        if (!tail) tail = head;
    }

    void moveToHead(std::shared_ptr<Node> node) {
        removeNode(node);
        addToHead(node);
    }

    void evictLRU() {
        if (!tail) return;
        cacheMap.erase(tail->key);
        removeNode(tail);
    }

public:
    explicit LRUCacheWithTTL(size_t cap) : capacity(cap), head(nullptr), tail(nullptr) {}

    std::optional<V> get(const K& key) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = cacheMap.find(key);
        if (it == cacheMap.end()) return std::nullopt;

        auto node = it->second;
        if (node->isExpired()) {
            cacheMap.erase(it);
            removeNode(node);
            return std::nullopt;
        }

        moveToHead(node);
        return node->value;
    }

    void put(const K& key, const V& value, std::optional<std::chrono::milliseconds> ttl = std::nullopt) {
        std::lock_guard<std::mutex> lock(mtx);
        bool hasTtl = ttl.has_value();
        auto expTime = hasTtl ? (std::chrono::steady_clock::now() + ttl.value())
                              : std::chrono::steady_clock::time_point::max();

        auto it = cacheMap.find(key);
        if (it != cacheMap.end()) {
            auto node = it->second;
            node->value = value;
            node->hasExpiry = hasTtl;
            node->expiryTime = expTime;
            moveToHead(node);
            return;
        }

        if (cacheMap.size() >= capacity) {
            evictLRU();
        }

        auto newNode = std::make_shared<Node>(key, value, hasTtl, expTime);
        addToHead(newNode);
        cacheMap[key] = newNode;
    }

    size_t size() const {
        std::lock_guard<std::mutex> lock(mtx);
        return cacheMap.size();
    }
};

int main() {
    LRUCacheWithTTL<std::string, int> cache(2);
    cache.put("A", 100);
    cache.put("B", 200, std::chrono::milliseconds(500));
    std::cout << "Key A: " << cache.get("A").value_or(-1) << "\n";
    cache.put("C", 300);
    std::cout << "Key B: " << (cache.get("B").has_value() ? "Exists" : "Null/Expired") << "\n";
    std::cout << "Key C: " << cache.get("C").value_or(-1) << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <memory>
#include <chrono>
#include <unordered_map>

enum class VehicleType { MOTORBIKE, CAR, TRUCK, EV_CAR };
enum class SpotType { SMALL, MEDIUM, LARGE, EV };

class Vehicle {
protected:
    std::string licensePlate;
    VehicleType type;
public:
    Vehicle(std::string plate, VehicleType t) : licensePlate(plate), type(t) {}
    virtual ~Vehicle() = default;
    VehicleType getType() const { return type; }
    std::string getPlate() const { return licensePlate; }
};

class ParkingSpot {
protected:
    int spotId;
    int floorNumber;
    SpotType spotType;
    bool isFree;
    std::shared_ptr<Vehicle> currentVehicle;
public:
    ParkingSpot(int id, int floor, SpotType type)
        : spotId(id), floorNumber(floor), spotType(type), isFree(true), currentVehicle(nullptr) {}
    virtual ~ParkingSpot() = default;
    bool isAvailable() const { return isFree; }
    int getId() const { return spotId; }
    int getFloor() const { return floorNumber; }
    virtual bool canFitVehicle(const std::shared_ptr<Vehicle>& v) const = 0;
    void assignVehicle(std::shared_ptr<Vehicle> v) { currentVehicle = v; isFree = false; }
    void removeVehicle() { currentVehicle = nullptr; isFree = true; }
};

class SmallSpot : public ParkingSpot {
public:
    SmallSpot(int id, int floor) : ParkingSpot(id, floor, SpotType::SMALL) {}
    bool canFitVehicle(const std::shared_ptr<Vehicle>& v) const override { return v->getType() == VehicleType::MOTORBIKE; }
};

class MediumSpot : public ParkingSpot {
public:
    MediumSpot(int id, int floor) : ParkingSpot(id, floor, SpotType::MEDIUM) {}
    bool canFitVehicle(const std::shared_ptr<Vehicle>& v) const override {
        return v->getType() == VehicleType::CAR || v->getType() == VehicleType::MOTORBIKE;
    }
};

class LargeSpot : public ParkingSpot {
public:
    LargeSpot(int id, int floor) : ParkingSpot(id, floor, SpotType::LARGE) {}
    bool canFitVehicle(const std::shared_ptr<Vehicle>& v) const override { return true; }
};

class EVSpot : public ParkingSpot {
public:
    EVSpot(int id, int floor) : ParkingSpot(id, floor, SpotType::EV) {}
    bool canFitVehicle(const std::shared_ptr<Vehicle>& v) const override { return v->getType() == VehicleType::EV_CAR; }
};

struct Ticket {
    std::string ticketId;
    std::shared_ptr<Vehicle> vehicle;
    std::shared_ptr<ParkingSpot> spot;
    std::chrono::system_clock::time_point entryTime;
};

class FeeStrategy {
public:
    virtual ~FeeStrategy() = default;
    virtual double calculateFee(const Ticket& ticket, std::chrono::system_clock::time_point exitTime) = 0;
};

class HourlyFeeStrategy : public FeeStrategy {
public:
    double calculateFee(const Ticket& ticket, std::chrono::system_clock::time_point exitTime) override {
        auto duration = std::chrono::duration_cast<std::chrono::hours>(exitTime - ticket.entryTime).count();
        if (duration <= 0) duration = 1;
        double rate = 20.0;
        if (ticket.vehicle->getType() == VehicleType::TRUCK) rate = 50.0;
        if (ticket.vehicle->getType() == VehicleType::EV_CAR) rate = 30.0;
        return duration * rate;
    }
};

class ParkingFloor {
    int floorNumber;
    std::vector<std::shared_ptr<ParkingSpot>> spots;
public:
    ParkingFloor(int num) : floorNumber(num) {}
    void addSpot(std::shared_ptr<ParkingSpot> spot) { spots.push_back(spot); }
    const std::vector<std::shared_ptr<ParkingSpot>>& getSpots() const { return spots; }
};

class ParkingStrategy {
public:
    virtual ~ParkingStrategy() = default;
    virtual std::shared_ptr<ParkingSpot> findSpot(
        const std::vector<std::shared_ptr<ParkingFloor>>& floors, const std::shared_ptr<Vehicle>& vehicle) = 0;
};

class NearestFirstParkingStrategy : public ParkingStrategy {
public:
    std::shared_ptr<ParkingSpot> findSpot(
        const std::vector<std::shared_ptr<ParkingFloor>>& floors, const std::shared_ptr<Vehicle>& vehicle) override {
        for (const auto& floor : floors) {
            for (const auto& spot : floor->getSpots()) {
                if (spot->isAvailable() && spot->canFitVehicle(vehicle)) return spot;
            }
        }
        return nullptr;
    }
};

class ParkingLot {
private:
    std::string name;
    std::vector<std::shared_ptr<ParkingFloor>> floors;
    std::shared_ptr<ParkingStrategy> parkingStrategy;
    std::shared_ptr<FeeStrategy> feeStrategy;
    std::unordered_map<std::string, Ticket> activeTickets;
    int ticketCounter = 0;
public:
    ParkingLot(std::string lotName, std::shared_ptr<ParkingStrategy> pStrat, std::shared_ptr<FeeStrategy> fStrat)
        : name(lotName), parkingStrategy(pStrat), feeStrategy(fStrat) {}
    void addFloor(std::shared_ptr<ParkingFloor> floor) { floors.push_back(floor); }

    std::shared_ptr<Ticket> parkVehicle(std::shared_ptr<Vehicle> vehicle) {
        auto spot = parkingStrategy->findSpot(floors, vehicle);
        if (!spot) {
            std::cout << "No free spot available for: " << vehicle->getPlate() << "\n";
            return nullptr;
        }
        spot->assignVehicle(vehicle);
        std::string ticketId = "TKT_" + std::to_string(++ticketCounter);
        Ticket t{ticketId, vehicle, spot, std::chrono::system_clock::now()};
        activeTickets[ticketId] = t;
        std::cout << "Parked " << vehicle->getPlate() << " at F" << spot->getFloor() << "-S" << spot->getId() << " [Ticket: " << ticketId << "]\n";
        return std::make_shared<Ticket>(t);
    }

    double unparkVehicle(const std::string& ticketId) {
        auto it = activeTickets.find(ticketId);
        if (it == activeTickets.end()) return 0.0;
        Ticket t = it->second;
        double fee = feeStrategy->calculateFee(t, std::chrono::system_clock::now());
        t.spot->removeVehicle();
        activeTickets.erase(it);
        std::cout << "Unparked " << ticketId << " | Fee: Rs " << fee << "\n";
        return fee;
    }
};

int main() {
    auto lot = std::make_unique<ParkingLot>("CityCenter", std::make_shared<NearestFirstParkingStrategy>(), std::make_shared<HourlyFeeStrategy>());
    auto f1 = std::make_shared<ParkingFloor>(1);
    f1->addSpot(std::make_shared<MediumSpot>(101, 1));
    lot->addFloor(f1);
    auto car = std::make_shared<Vehicle>("DL-01-AB-1234", VehicleType::CAR);
    auto tkt = lot->parkVehicle(car);
    if (tkt) lot->unparkVehicle(tkt->ticketId);
    return 0;
}

#include <iostream>
#include <vector>
#include <memory>
#include <stack>

enum class PieceType { NONE = 0, X = 1, O = -1 };

struct Move {
    int row;
    int col;
    PieceType piece;
};

class Board {
private:
    int n;
    std::vector<std::vector<PieceType>> grid;
    std::vector<int> rowCounts;
    std::vector<int> colCounts;
    int diagCount = 0;
    int antiDiagCount = 0;
    int movesMade = 0;

public:
    explicit Board(int size)
        : n(size), grid(size, std::vector<PieceType>(size, PieceType::NONE)),
          rowCounts(size, 0), colCounts(size, 0) {}

    int getSize() const { return n; }
    bool isFull() const { return movesMade == n * n; }
    bool isValidMove(int r, int c) const { return (r >= 0 && r < n && c >= 0 && c < n && grid[r][c] == PieceType::NONE); }

    bool makeMove(int r, int c, PieceType piece) {
        grid[r][c] = piece;
        movesMade++;
        int val = (piece == PieceType::X) ? 1 : -1;
        rowCounts[r] += val;
        colCounts[c] += val;
        if (r == c) diagCount += val;
        if (r + c == n - 1) antiDiagCount += val;

        int target = (piece == PieceType::X) ? n : -n;
        return (rowCounts[r] == target || colCounts[c] == target || diagCount == target || antiDiagCount == target);
    }

    void undoMove(int r, int c) {
        if (grid[r][c] == PieceType::NONE) return;
        PieceType piece = grid[r][c];
        int val = (piece == PieceType::X) ? 1 : -1;
        rowCounts[r] -= val;
        colCounts[c] -= val;
        if (r == c) diagCount -= val;
        if (r + c == n - 1) antiDiagCount -= val;
        grid[r][c] = PieceType::NONE;
        movesMade--;
    }

    void print() const {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                char ch = (grid[i][j] == PieceType::X) ? 'X' : (grid[i][j] == PieceType::O ? 'O' : '.');
                std::cout << ch << " ";
            }
            std::cout << "\n";
        }
    }
};

class Player {
protected:
    std::string name;
    PieceType piece;
public:
    Player(std::string n, PieceType p) : name(n), piece(p) {}
    virtual ~Player() = default;
    std::string getName() const { return name; }
    PieceType getPiece() const { return piece; }
    virtual std::pair<int, int> getNextMove(const Board& board) = 0;
};

class BotPlayer : public Player {
public:
    BotPlayer(std::string n, PieceType p) : Player(n, p) {}
    std::pair<int, int> getNextMove(const Board& board) override {
        for (int i = 0; i < board.getSize(); ++i) {
            for (int j = 0; j < board.getSize(); ++j) {
                if (board.isValidMove(i, j)) return {i, j};
            }
        }
        return {-1, -1};
    }
};

class TicTacToeGame {
private:
    Board board;
    std::vector<std::shared_ptr<Player>> players;
    int currentPlayerIndex = 0;
    std::stack<Move> moveHistory;

public:
    TicTacToeGame(int size, std::shared_ptr<Player> p1, std::shared_ptr<Player> p2) : board(size) {
        players.push_back(p1);
        players.push_back(p2);
    }

    void undoLastMove() {
        if (moveHistory.empty()) return;
        Move last = moveHistory.top();
        moveHistory.pop();
        board.undoMove(last.row, last.col);
        currentPlayerIndex = (currentPlayerIndex - 1 + players.size()) % players.size();
        std::cout << "Undid move at (" << last.row << ", " << last.col << ")\n";
    }

    void playRound() {
        auto current = players[currentPlayerIndex];
        auto [r, c] = current->getNextMove(board);
        if (!board.isValidMove(r, c)) return;

        bool won = board.makeMove(r, c, current->getPiece());
        moveHistory.push({r, c, current->getPiece()});
        std::cout << current->getName() << " moved to (" << r << ", " << c << ")\n";

        if (won) {
            board.print();
            std::cout << current->getName() << " WON!\n";
            return;
        }
        currentPlayerIndex = (currentPlayerIndex + 1) % players.size();
    }
};

int main() {
    auto p1 = std::make_shared<BotPlayer>("AlphaBot", PieceType::X);
    auto p2 = std::make_shared<BotPlayer>("BetaBot", PieceType::O);
    TicTacToeGame game(3, p1, p2);
    game.playRound();
    game.playRound();
    game.undoLastMove();
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <memory>
#include <unordered_map>
#include <queue>
#include <chrono>

enum class BookStatus { AVAILABLE, LOANED, RESERVED };

class Book {
    std::string isbn;
    std::string title;
    std::string author;
public:
    Book(std::string i, std::string t, std::string a) : isbn(i), title(t), author(a) {}
    std::string getTitle() const { return title; }
    std::string getAuthor() const { return author; }
};

class Member;

class BookItem {
private:
    std::string barcode;
    std::shared_ptr<Book> bookDetails;
    BookStatus status;
    std::chrono::system_clock::time_point dueDate;
    std::queue<std::shared_ptr<Member>> reservationQueue;
public:
    BookItem(std::string code, std::shared_ptr<Book> book)
        : barcode(code), bookDetails(book), status(BookStatus::AVAILABLE) {}
    std::string getBarcode() const { return barcode; }
    std::shared_ptr<Book> getDetails() const { return bookDetails; }
    BookStatus getStatus() const { return status; }
    void setStatus(BookStatus s) { status = s; }
    void setDueDate(std::chrono::system_clock::time_point date) { dueDate = date; }
    std::chrono::system_clock::time_point getDueDate() const { return dueDate; }
    void addReservation(std::shared_ptr<Member> member) {
        reservationQueue.push(member);
        status = BookStatus::RESERVED;
    }
    std::shared_ptr<Member> popNextReservation() {
        if (reservationQueue.empty()) return nullptr;
        auto next = reservationQueue.front();
        reservationQueue.pop();
        if (reservationQueue.empty()) status = BookStatus::AVAILABLE;
        return next;
    }
};

class Member : public std::enable_shared_from_this<Member> {
private:
    std::string memberId;
    std::string name;
    int activeCheckouts = 0;
public:
    Member(std::string id, std::string n) : memberId(id), name(n) {}
    std::string getName() const { return name; }
    bool canCheckout() const { return activeCheckouts < 5; }
    void incrementCheckout() { activeCheckouts++; }
    void decrementCheckout() { if (activeCheckouts > 0) activeCheckouts--; }
    void notifyBookAvailable(const std::string& title) {
        std::cout << "[NOTIFICATION to " << name << "]: Book '" << title << "' is now available!\n";
    }
};

class LibraryService {
private:
    std::unordered_map<std::string, std::shared_ptr<BookItem>> itemsByBarcode;
public:
    void addItem(std::shared_ptr<BookItem> item) { itemsByBarcode[item->getBarcode()] = item; }
    bool checkoutBook(const std::string& barcode, std::shared_ptr<Member> member) {
        auto item = itemsByBarcode[barcode];
        if (!item || item->getStatus() != BookStatus::AVAILABLE || !member->canCheckout()) return false;
        item->setStatus(BookStatus::LOANED);
        item->setDueDate(std::chrono::system_clock::now() + std::chrono::hours(24 * 14));
        member->incrementCheckout();
        std::cout << "Issued '" << item->getDetails()->getTitle() << "' to " << member->getName() << "\n";
        return true;
    }
    void returnBook(const std::string& barcode, std::shared_ptr<Member> member) {
        auto item = itemsByBarcode[barcode];
        if (!item || item->getStatus() != BookStatus::LOANED) return;
        member->decrementCheckout();
        auto nextMember = item->popNextReservation();
        if (nextMember) {
            item->setStatus(BookStatus::RESERVED);
            nextMember->notifyBookAvailable(item->getDetails()->getTitle());
        } else {
            item->setStatus(BookStatus::AVAILABLE);
        }
        std::cout << "Book returned successfully.\n";
    }
    void reserveBook(const std::string& barcode, std::shared_ptr<Member> member) {
        auto item = itemsByBarcode[barcode];
        if (item) item->addReservation(member);
    }
};

int main() {
    LibraryService library;
    auto book = std::make_shared<Book>("978-0132350884", "Clean Code", "Robert C. Martin");
    auto copy = std::make_shared<BookItem>("BC_01", book);
    library.addItem(copy);
    auto rahul = std::make_shared<Member>("M1", "Rahul");
    auto priya = std::make_shared<Member>("M2", "Priya");
    library.checkoutBook("BC_01", rahul);
    library.reserveBook("BC_01", priya);
    library.returnBook("BC_01", rahul);
    return 0;
}

#include <iostream>
#include <unordered_map>
#include <memory>
#include <string>

struct Item {
    std::string name;
    int price;
    int quantity;
};

class VendingMachine;

class State {
public:
    virtual ~State() = default;
    virtual void insertMoney(VendingMachine& vm, int amount) = 0;
    virtual void selectProduct(VendingMachine& vm, const std::string& code) = 0;
    virtual void dispense(VendingMachine& vm) = 0;
    virtual void cancel(VendingMachine& vm) = 0;
};

class VendingMachine {
private:
    std::shared_ptr<State> idleState;
    std::shared_ptr<State> hasMoneyState;
    std::shared_ptr<State> dispenseState;
    std::shared_ptr<State> currentState;
    int currentBalance = 0;
    std::string selectedItemCode = "";
    std::unordered_map<std::string, Item> inventory;

public:
    VendingMachine();
    void setState(std::shared_ptr<State> state) { currentState = state; }
    std::shared_ptr<State> getIdleState() { return idleState; }
    std::shared_ptr<State> getHasMoneyState() { return hasMoneyState; }
    std::shared_ptr<State> getDispenseState() { return dispenseState; }
    void addBalance(int amt) { currentBalance += amt; }
    int getBalance() const { return currentBalance; }
    void resetBalance() { currentBalance = 0; }
    void setSelectedItem(const std::string& code) { selectedItemCode = code; }
    std::string getSelectedItem() const { return selectedItemCode; }
    void addInventory(const std::string& code, Item item) { inventory[code] = item; }
    bool hasItem(const std::string& code) const {
        auto it = inventory.find(code);
        return it != inventory.end() && it->second.quantity > 0;
    }
    Item& getItem(const std::string& code) { return inventory[code]; }

    void insertMoney(int amt) { currentState->insertMoney(*this, amt); }
    void selectProduct(const std::string& code) { currentState->selectProduct(*this, code); }
    void dispense() { currentState->dispense(*this); }
    void cancel() { currentState->cancel(*this); }
};

class IdleState : public State {
public:
    void insertMoney(VendingMachine& vm, int amount) override {
        vm.addBalance(amount);
        std::cout << "Inserted Rs " << amount << ". Total: Rs " << vm.getBalance() << "\n";
        vm.setState(vm.getHasMoneyState());
    }
    void selectProduct(VendingMachine&, const std::string&) override { std::cout << "Insert money first!\n"; }
    void dispense(VendingMachine&) override { std::cout << "Cannot dispense.\n"; }
    void cancel(VendingMachine&) override { std::cout << "Nothing to cancel.\n"; }
};

class HasMoneyState : public State {
public:
    void insertMoney(VendingMachine& vm, int amount) override {
        vm.addBalance(amount);
        std::cout << "Added Rs " << amount << ". Total: Rs " << vm.getBalance() << "\n";
    }
    void selectProduct(VendingMachine& vm, const std::string& code) override {
        if (!vm.hasItem(code)) {
            std::cout << "Item unavailable!\n";
            return;
        }
        Item& item = vm.getItem(code);
        if (vm.getBalance() < item.price) {
            std::cout << "Insufficient balance! Need Rs " << item.price << "\n";
            return;
        }
        vm.setSelectedItem(code);
        vm.setState(vm.getDispenseState());
        vm.dispense();
    }
    void dispense(VendingMachine&) override { std::cout << "Select item first.\n"; }
    void cancel(VendingMachine& vm) override {
        std::cout << "Refunded Rs " << vm.getBalance() << "\n";
        vm.resetBalance();
        vm.setState(vm.getIdleState());
    }
};

class DispenseState : public State {
public:
    void insertMoney(VendingMachine&, int) override { std::cout << "Dispensing in progress...\n"; }
    void selectProduct(VendingMachine&, const std::string&) override { std::cout << "Dispensing in progress...\n"; }
    void dispense(VendingMachine& vm) override {
        Item& item = vm.getItem(vm.getSelectedItem());
        item.quantity--;
        int change = vm.getBalance() - item.price;
        std::cout << "DISPENSED: " << item.name << "\n";
        if (change > 0) std::cout << "Returned Change: Rs " << change << "\n";
        vm.resetBalance();
        vm.setSelectedItem("");
        vm.setState(vm.getIdleState());
    }
    void cancel(VendingMachine&) override { std::cout << "Cannot cancel during dispense!\n"; }
};

VendingMachine::VendingMachine() {
    idleState = std::make_shared<IdleState>();
    hasMoneyState = std::make_shared<HasMoneyState>();
    dispenseState = std::make_shared<DispenseState>();
    currentState = idleState;
}

int main() {
    VendingMachine vm;
    vm.addInventory("A1", {"Chips", 20, 2});
    vm.insertMoney(50);
    vm.selectProduct("A1");
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <memory>
#include <cmath>
