enum class SplitType { EQUAL, EXACT, PERCENT };

struct Split {
    std::string userId;
    double amount;
    double percent;
    Split(std::string id, double amt = 0.0, double pct = 0.0) : userId(id), amount(amt), percent(pct) {}
};

class SplitStrategy {
public:
    virtual ~SplitStrategy() = default;
    virtual bool validateAndCompute(double totalAmount, std::vector<Split>& splits) = 0;
};

class EqualSplitStrategy : public SplitStrategy {
public:
    bool validateAndCompute(double totalAmount, std::vector<Split>& splits) override {
        if (splits.empty()) return false;
        double n = static_cast<double>(splits.size());
        double baseShare = std::round((totalAmount / n) * 100.0) / 100.0;
        double runningTotal = 0.0;
        for (size_t i = 0; i < splits.size() - 1; ++i) {
            splits[i].amount = baseShare;
            runningTotal += baseShare;
        }
        splits.back().amount = std::round((totalAmount - runningTotal) * 100.0) / 100.0;
        return true;
    }
};

class ExactSplitStrategy : public SplitStrategy {
public:
    bool validateAndCompute(double totalAmount, std::vector<Split>& splits) override {
        double sum = 0.0;
        for (const auto& s : splits) sum += s.amount;
        return std::fabs(sum - totalAmount) < 0.001;
    }
};

class PercentSplitStrategy : public SplitStrategy {
public:
    bool validateAndCompute(double totalAmount, std::vector<Split>& splits) override {
        double totalPct = 0.0;
        for (const auto& s : splits) totalPct += s.percent;
        if (std::fabs(totalPct - 100.0) > 0.001) return false;
        for (auto& s : splits) {
            s.amount = std::round(((totalAmount * s.percent) / 100.0) * 100.0) / 100.0;
        }
        return true;
    }
};

struct Transaction {
    std::string debtor;
    std::string creditor;
    double amount;
};

class SplitwiseService {
private:
    std::unordered_map<std::string, std::unordered_map<std::string, double>> balanceSheet;
    std::unordered_map<SplitType, std::shared_ptr<SplitStrategy>> strategies;

public:
    SplitwiseService() {
        strategies[SplitType::EQUAL] = std::make_shared<EqualSplitStrategy>();
        strategies[SplitType::EXACT] = std::make_shared<ExactSplitStrategy>();
        strategies[SplitType::PERCENT] = std::make_shared<PercentSplitStrategy>();
    }

    bool addExpense(const std::string& paidBy, double totalAmount, SplitType type, std::vector<Split> splits) {
        if (strategies.find(type) == strategies.end() || !strategies[type]->validateAndCompute(totalAmount, splits)) {
            std::cout << "Invalid expense parameters or splits mismatch!\n";
            return false;
        }
        for (const auto& split : splits) {
            if (split.userId == paidBy) continue;
            balanceSheet[split.userId][paidBy] += split.amount;
            balanceSheet[paidBy][split.userId] -= split.amount;
        }
        std::cout << "Successfully recorded expense of Rs " << totalAmount << " paid by " << paidBy << "\n";
        return true;
    }

    void showUserBalances(const std::string& userId) {
        std::cout << "--- Balances for " << userId << " ---\n";
        bool hasBalance = false;
        for (const auto& [otherUser, net] : balanceSheet[userId]) {
            if (std::fabs(net) > 0.01) {
                hasBalance = true;
                if (net > 0) std::cout << userId << " owes " << otherUser << ": Rs " << net << "\n";
                else std::cout << otherUser << " owes " << userId << " : Rs " << -net << "\n";
            }
        }
        if (!hasBalance) std::cout << "All settled up!\n";
    }

    std::vector<Transaction> simplifyDebts() {
        std::unordered_map<std::string, double> netAmounts;
        for (const auto& [u1, pairMap] : balanceSheet) {
            for (const auto& [u2, amt] : pairMap) {
                netAmounts[u1] -= amt; // Negative amt means u1 is owed money
            }
        }
        using Account = std::pair<double, std::string>;
        std::priority_queue<Account> creditors;
        std::priority_queue<Account, std::vector<Account>, std::greater<Account>> debtors;

        for (const auto& [user, net] : netAmounts) {
            double rounded = std::round(net * 100.0) / 100.0;
            if (rounded > 0.01) creditors.push({rounded, user});
            else if (rounded < -0.01) debtors.push({rounded, user});
        }

        std::vector<Transaction> transactions;
        while (!creditors.empty() && !debtors.empty()) {
            auto [creditAmt, credUser] = creditors.top(); creditors.pop();
            auto [debtAmt, debtUser] = debtors.top(); debtors.pop();
            double settle = std::min(creditAmt, -debtAmt);
            transactions.push_back({debtUser, credUser, settle});

            double remCredit = creditAmt - settle;
            double remDebt = debtAmt + settle;
            if (remCredit > 0.01) creditors.push({remCredit, credUser});
            if (remDebt < -0.01) debtors.push({remDebt, debtUser});
        }
        return transactions;
    }
};

int main() {
    SplitwiseService splitwise;
    splitwise.addExpense("UserA", 300.0, SplitType::EQUAL, { {"UserA"}, {"UserB"}, {"UserC"} });
    splitwise.addExpense("UserB", 120.0, SplitType::EXACT, { {"UserA", 40.0}, {"UserC", 80.0} });
    splitwise.showUserBalances("UserA");

    std::cout << "\n--- Simplified Transactions (Minimum Cash Flow) ---\n";
    auto settlements = splitwise.simplifyDebts();
    for (const auto& tx : settlements) {
        std::cout << tx.debtor << " -> pays Rs " << tx.amount << " -> " << tx.creditor << "\n";
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <set>
#include <memory>
#include <cmath>
#include <algorithm>

enum class Direction { NONE, UP, DOWN };
enum class CarState { IDLE, MOVING, STOPPED };

struct Request {
    int floor;
    Direction direction;
};

class ElevatorCar {
private:
    int id;
    int currentFloor = 0;
    Direction currentDirection = Direction::NONE;
    CarState state = CarState::IDLE;
    std::set<int> upRequests;
    std::set<int, std::greater<int>> downRequests;
    int currentWeight = 0;
    static constexpr int MAX_WEIGHT_CAPACITY = 800; // in kg

public:
    ElevatorCar(int carId) : id(carId) {}

    int getId() const { return id; }
    int getCurrentFloor() const { return currentFloor; }
    Direction getDirection() const { return currentDirection; }
    CarState getState() const { return state; }

    void addRequest(int floor) {
        if (floor > currentFloor) upRequests.insert(floor);
        else if (floor < currentFloor) downRequests.insert(floor);
        else openDoors();

        if (currentDirection == Direction::NONE) {
            currentDirection = (floor >= currentFloor) ? Direction::UP : Direction::DOWN;
            state = CarState::MOVING;
        }
    }

    bool updateWeight(int weight) {
        currentWeight = weight;
        if (currentWeight > MAX_WEIGHT_CAPACITY) {
            std::cout << "[ALERT Car " << id << "]: OVERLOAD! Weight: " << currentWeight << "kg. Remove passengers.\n";
            return false;
        }
        return true;
    }

    void step() {
        if (currentWeight > MAX_WEIGHT_CAPACITY) return;

        if (currentDirection == Direction::UP) {
            if (!upRequests.empty()) {
                int nextTarget = *upRequests.begin();
                currentFloor++;
                std::cout << "Car " << id << " moving UP to Floor " << currentFloor << "\n";
                if (currentFloor == nextTarget) {
                    openDoors();
                    upRequests.erase(currentFloor);
                }
            } else if (!downRequests.empty()) {
                currentDirection = Direction::DOWN;
            } else {
                currentDirection = Direction::NONE;
                state = CarState::IDLE;
            }
        } else if (currentDirection == Direction::DOWN) {
            if (!downRequests.empty()) {
                int nextTarget = *downRequests.begin();
                currentFloor--;
                std::cout << "Car " << id << " moving DOWN to Floor " << currentFloor << "\n";
                if (currentFloor == nextTarget) {
                    openDoors();
                    downRequests.erase(currentFloor);
                }
            } else if (!upRequests.empty()) {
                currentDirection = Direction::UP;
            } else {
                currentDirection = Direction::NONE;
                state = CarState::IDLE;
            }
        }
    }

    void openDoors() {
        std::cout << "[DOOR OPEN Car " << id << "]: Stopped at Floor " << currentFloor << " to let passengers in/out\n";
    }

    int calculateCost(int targetFloor, Direction dir) const {
        int cost = 0;
        if (currentDirection == Direction::NONE) return std::abs(currentFloor - targetFloor);
        if (currentDirection == dir) {
            if ((dir == Direction::UP && targetFloor >= currentFloor) ||
                (dir == Direction::DOWN && targetFloor <= currentFloor)) {
                return std::abs(currentFloor - targetFloor);
            }
        }
        return 1000 + std::abs(currentFloor - targetFloor); // Penalty for opposite trajectory
    }
};

class ElevatorController {
private:
    std::vector<std::shared_ptr<ElevatorCar>> elevators;

public:
    ElevatorController(int numCars) {
        for (int i = 1; i <= numCars; ++i) {
            elevators.push_back(std::make_shared<ElevatorCar>(i));
        }
    }

    void requestElevator(int floor, Direction dir) {
        std::shared_ptr<ElevatorCar> bestCar = nullptr;
        int minCost = 1e9;
        for (const auto& car : elevators) {
            int cost = car->calculateCost(floor, dir);
            if (cost < minCost) {
                minCost = cost;
                bestCar = car;
            }
        }
        if (bestCar) {
            std::cout << "Assigning Hallway Call (Floor " << floor << ") to Car " << bestCar->getId() << "\n";
            bestCar->addRequest(floor);
        }
    }

    void pressInternalButton(int carId, int destinationFloor) {
        for (auto& car : elevators) {
            if (car->getId() == carId) {
                std::cout << "Car " << carId << " internal button pressed for Floor " << destinationFloor << "\n";
                car->addRequest(destinationFloor);
                return;
            }
        }
    }

    void stepSimulation() {
        for (auto& car : elevators) car->step();
    }
};

int main() {
    ElevatorController controller(2); // 2 elevators in high-rise
    controller.requestElevator(5, Direction::UP);
    controller.requestElevator(3, Direction::DOWN);

    std::cout << "--- Running Step 1 Simulation ---\n";
    controller.stepSimulation();
    controller.stepSimulation();

    controller.pressInternalButton(1, 8);
    std::cout << "--- Running Further Steps ---\n";
    for (int i = 0; i < 5; ++i) controller.stepSimulation();

    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <memory>
#include <chrono>
#include <mutex>
#include <optional>

enum class SeatStatus { AVAILABLE, TEMPORARILY_LOCKED, BOOKED };
enum class SeatTier { SILVER, GOLD, PLATINUM };

struct Seat {
    std::string seatId;
    int row;
    int col;
    SeatTier tier;
    SeatStatus status = SeatStatus::AVAILABLE;
    std::string lockedByUserId = "";
    std::chrono::steady_clock::time_point lockExpiryTime;

    bool isAvailable() const {
        if (status == SeatStatus::BOOKED) return false;
        if (status == SeatStatus::TEMPORARILY_LOCKED) {
            return std::chrono::steady_clock::now() > lockExpiryTime;
        }
        return true;
    }
};

class Show {
private:
    std::string showId;
    std::string movieName;
    std::unordered_map<std::string, Seat> seats;
    mutable std::mutex showMutex;

public:
    Show(std::string id, std::string movie) : showId(id), movieName(movie) {}

    void addSeat(const Seat& seat) {
        seats[seat.seatId] = seat;
    }

    bool temporaryLockSeats(const std::vector<std::string>& seatIds, const std::string& userId, std::chrono::seconds lockDuration) {
        std::lock_guard<std::mutex> lock(showMutex);
        auto now = std::chrono::steady_clock::now();

        for (const auto& id : seatIds) {
            auto it = seats.find(id);
            if (it == seats.end() || !it->second.isAvailable()) {
                std::cout << "Seat " << id << " is already locked or booked! Aborting.\n";
                return false;
            }
        }

        for (const auto& id : seatIds) {
            seats[id].status = SeatStatus::TEMPORARILY_LOCKED;
            seats[id].lockedByUserId = userId;
            seats[id].lockExpiryTime = now + lockDuration;
        }
        std::cout << "Seats successfully locked for user: " << userId << "\n";
        return true;
    }

    bool confirmBooking(const std::vector<std::string>& seatIds, const std::string& userId) {
        std::lock_guard<std::mutex> lock(showMutex);
        auto now = std::chrono::steady_clock::now();

        for (const auto& id : seatIds) {
            auto it = seats.find(id);
            if (it == seats.end()) return false;
            if (it->second.status != SeatStatus::TEMPORARILY_LOCKED ||
                it->second.lockedByUserId != userId ||
                now > it->second.lockExpiryTime) {
                std::cout << "Lock expired or invalid for seat " << id << "!\n";
                return false;
            }
        }

        for (const auto& id : seatIds) {
            seats[id].status = SeatStatus::BOOKED;
            seats[id].lockedByUserId = "";
        }
        std::cout << "Booking confirmed for user: " << userId << "!\n";
        return true;
    }
};

int main() {
    auto show = std::make_shared<Show>("SHOW_101", "Inception");
    show->addSeat({"A1", 1, 1, SeatTier::PLATINUM});
    show->addSeat({"A2", 1, 2, SeatTier::PLATINUM});

    std::cout << "--- Scenario 1: User 1 locks seats with 2-second timeout ---\n";
    bool u1Lock = show->temporaryLockSeats({"A1", "A2"}, "User_1", std::chrono::seconds(2));

    std::cout << "\n--- Scenario 2: Concurrent User 2 tries to lock the same seats ---\n";
    bool u2Lock = show->temporaryLockSeats({"A1"}, "User_2", std::chrono::seconds(5));

    std::cout << "\n--- Scenario 3: User 1 confirms booking before timeout ---\n";
    if (u1Lock) {
        show->confirmBooking({"A1", "A2"}, "User_1");
    }
    return 0;
}

#include <iostream>
#include <memory>
#include <string>

class ATM;

class CashDispenser {
protected:
    std::shared_ptr<CashDispenser> nextHandler;
    int denomination;
    int availableNotes;

public:
    CashDispenser(int denom, int notes) : denomination(denom), availableNotes(notes), nextHandler(nullptr) {}
    virtual ~CashDispenser() = default;

    void setNextHandler(std::shared_ptr<CashDispenser> next) {
        nextHandler = next;
    }

    virtual bool dispense(int& remainingAmount) {
        int neededNotes = remainingAmount / denomination;
        int notesToDispense = std::min(neededNotes, availableNotes);

        if (notesToDispense > 0) {
            remainingAmount -= (notesToDispense * denomination);
            availableNotes -= notesToDispense;
            std::cout << "Dispensing " << notesToDispense << " notes of Rs " << denomination << "\n";
        }

        if (remainingAmount > 0) {
            if (nextHandler) return nextHandler->dispense(remainingAmount);
            return false;
        }
        return true;
    }
};

class ATMState {
public:
    virtual ~ATMState() = default;
    virtual void insertCard(ATM& atm) = 0;
    virtual void authenticatePin(ATM& atm, const std::string& pin) = 0;
    virtual void withdrawCash(ATM& atm, int amount) = 0;
    virtual void ejectCard(ATM& atm) = 0;
};

class ATM {
private:
    std::shared_ptr<ATMState> idleState;
    std::shared_ptr<ATMState> hasCardState;
    std::shared_ptr<ATMState> pinVerifiedState;
    std::shared_ptr<ATMState> currentState;
    std::shared_ptr<CashDispenser> dispenserChain;
    int userBalance = 10000;

public:
    ATM();
    void setState(std::shared_ptr<ATMState> state) { currentState = state; }
    std::shared_ptr<ATMState> getIdleState() { return idleState; }
    std::shared_ptr<ATMState> getHasCardState() { return hasCardState; }
    std::shared_ptr<ATMState> getPinVerifiedState() { return pinVerifiedState; }

    int getBalance() const { return userBalance; }
    void deductBalance(int amt) { userBalance -= amt; }
    std::shared_ptr<CashDispenser> getDispenser() { return dispenserChain; }

    void insertCard() { currentState->insertCard(*this); }
    void authenticatePin(const std::string& pin) { currentState->authenticatePin(*this, pin); }
    void withdrawCash(int amount) { currentState->withdrawCash(*this, amount); }
    void ejectCard() { currentState->ejectCard(*this); }
};

class IdleState : public ATMState {
public:
    void insertCard(ATM& atm) override {
        std::cout << "Card inserted. Please enter 4-digit PIN.\n";
        atm.setState(atm.getHasCardState());
    }
    void authenticatePin(ATM&, const std::string&) override { std::cout << "Please insert card first!\n"; }
    void withdrawCash(ATM&, int) override { std::cout << "Please insert card first!\n"; }
    void ejectCard(ATM&) override { std::cout << "No card in ATM.\n"; }
};

class HasCardState : public ATMState {
public:
    void insertCard(ATM&) override { std::cout << "Card already present.\n"; }
    void authenticatePin(ATM& atm, const std::string& pin) override {
        if (pin == "1234") {
            std::cout << "PIN verified successfully!\n";
            atm.setState(atm.getPinVerifiedState());
        } else {
            std::cout << "Incorrect PIN! Ejecting card.\n";
            atm.setState(atm.getIdleState());
        }
    }
    void withdrawCash(ATM&, int) override { std::cout << "Enter PIN first!\n"; }
    void ejectCard(ATM& atm) override {
        std::cout << "Card ejected.\n";
        atm.setState(atm.getIdleState());
    }
};

class PinVerifiedState : public ATMState {
public:
    void insertCard(ATM&) override { std::cout << "Card already present.\n"; }
    void authenticatePin(ATM&, const std::string&) override { std::cout << "PIN already authenticated.\n"; }
    void withdrawCash(ATM& atm, int amount) override {
        if (amount > atm.getBalance()) {
            std::cout << "Insufficient account balance! Available: Rs " << atm.getBalance() << "\n";
            return;
        }
        int rem = amount;
        if (atm.getDispenser()->dispense(rem)) {
            atm.deductBalance(amount);
            std::cout << "Cash withdrawal complete! Updated Balance: Rs " << atm.getBalance() << "\n";
        } else {
            std::cout << "ATM unable to dispense requested denomination mix! Transaction aborted.\n";
        }
        atm.ejectCard();
    }
    void ejectCard(ATM& atm) override {
        std::cout << "Card ejected. Thank you for banking with us!\n";
        atm.setState(atm.getIdleState());
    }
};

ATM::ATM() {
    idleState = std::make_shared<IdleState>();
    hasCardState = std::make_shared<HasCardState>();
    pinVerifiedState = std::make_shared<PinVerifiedState>();
    currentState = idleState;

    auto d2000 = std::make_shared<CashDispenser>(2000, 5);
    auto d500 = std::make_shared<CashDispenser>(500, 10);
    auto d200 = std::make_shared<CashDispenser>(200, 20);
    auto d100 = std::make_shared<CashDispenser>(100, 30);

    d2000->setNextHandler(d500);
    d500->setNextHandler(d200);
    d200->setNextHandler(d100);
    dispenserChain = d2000;
}

int main() {
    ATM atm;
    std::cout << "--- Flow 1: Successful Withdrawal of Rs 3700 ---\n";
    atm.insertCard();
    atm.authenticatePin("1234");
    atm.withdrawCash(3700);

    std::cout << "\n--- Flow 2: Wrong PIN Flow ---\n";
    atm.insertCard();
    atm.authenticatePin("0000");
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <queue>
#include <memory>
#include <random>

class Dice {
private:
    int sides;
    std::mt19937 rng;
    std::uniform_int_distribution<int> dist;

public:
    explicit Dice(int numSides = 6)
        : sides(numSides), rng(std::random_device{}()), dist(1, numSides) {}

    int roll() {
        return dist(rng);
    }
};

struct Player {
    std::string id;
    std::string name;
    int currentPosition = 0;
    bool hasWon = false;

    Player(std::string pId, std::string pName) : id(pId), name(pName) {}
};

class Board {
private:
    int totalSquares;
    std::unordered_map<int, int> jumps; // start -> destination (both snakes & ladders)

public:
    explicit Board(int size = 100) : totalSquares(size) {}

    int getTotalSquares() const { return totalSquares; }

    bool addSnake(int head, int tail) {
        if (head <= tail || head >= totalSquares || tail < 1) return false;
        jumps[head] = tail;
        return true;
    }

    bool addLadder(int start, int end) {
        if (start >= end || start < 1 || end > totalSquares) return false;
        jumps[start] = end;
        return true;
    }

    int getFinalPosition(int targetSquare) const {
        auto it = jumps.find(targetSquare);
        if (it != jumps.end()) {
            return it->second;
        }
        return targetSquare;
    }
};

class SnakeAndLadderGame {
private:
    Board board;
    std::vector<Dice> diceList;
    std::queue<std::shared_ptr<Player>> playerQueue;
    std::vector<std::shared_ptr<Player>> winners;

public:
    SnakeAndLadderGame(int boardSize, int numDice)
        : board(boardSize) {
        for (int i = 0; i < numDice; ++i) {
            diceList.emplace_back(6);
        }
    }

    void addPlayer(const std::string& id, const std::string& name) {
        playerQueue.push(std::make_shared<Player>(id, name));
    }

    void addSnake(int head, int tail) { board.addSnake(head, tail); }
    void addLadder(int start, int end) { board.addLadder(start, end); }

    int rollAllDice() {
        int total = 0;
        for (auto& dice : diceList) {
            total += dice.roll();
        }
        return total;
    }

    bool playTurn() {
        if (playerQueue.empty()) return false;

        auto player = playerQueue.front();
        playerQueue.pop();

        int roll = rollAllDice();
        int nextSquare = player->currentPosition + roll;

        std::cout << player->name << " rolled a " << roll << ". ";

        if (nextSquare > board.getTotalSquares()) {
            std::cout << "Exceeds " << board.getTotalSquares() << ", stays at square "
                      << player->currentPosition << ".\n";
            playerQueue.push(player);
            return false;
        }

        int finalSquare = board.getFinalPosition(nextSquare);
        if (finalSquare > nextSquare) {
            std::cout << "CLIMBED LADDER from " << nextSquare << " to " << finalSquare << "! ";
        } else if (finalSquare < nextSquare) {
            std::cout << "BITTEN BY SNAKE from " << nextSquare << " to " << finalSquare << "! ";
        }

        player->currentPosition = finalSquare;
        std::cout << player->name << " is now at square " << player->currentPosition << ".\n";

        if (player->currentPosition == board.getTotalSquares()) {
            player->hasWon = true;
            winners.push_back(player);
            std::cout << "*** " << player->name << " WON THE GAME! Rank: "
                      << winners.size() << " ***\n";
            return true;
        }

        playerQueue.push(player);
        return false;
    }
};

int main() {
    SnakeAndLadderGame game(100, 1);

    game.addLadder(4, 25);
    game.addLadder(13, 46);
    game.addLadder(33, 49);
    game.addLadder(50, 69);
    game.addLadder(62, 81);

    game.addSnake(40, 3);
    game.addSnake(43, 18);
    game.addSnake(54, 31);
    game.addSnake(89, 53);
    game.addSnake(99, 41);

    game.addPlayer("P1", "Aman");
    game.addPlayer("P2", "Rohit");

    std::cout << "--- Starting Snake & Ladder Match ---\n";
    int turns = 0;
    while (turns < 30) {
        bool won = game.playTurn();
        turns++;
        if (won) break;
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <memory>
