enum class Color { WHITE, BLACK };
enum class PieceType { PAWN, ROOK, KNIGHT, BISHOP, QUEEN, KING };

struct Position {
    int row;
    int col;
    bool operator==(const Position& other) const {
        return row == other.row && col == other.col;
    }
};

class Piece {
protected:
    Color color;
    PieceType type;

public:
    Piece(Color c, PieceType t) : color(c), type(t) {}
    virtual ~Piece() = default;

    Color getColor() const { return color; }
    PieceType getType() const { return type; }

    virtual bool canMove(Position start, Position end, const std::vector<std::vector<std::shared_ptr<Piece>>>& board) const = 0;
};

class Board {
public:
    static constexpr int SIZE = 8;
    std::vector<std::vector<std::shared_ptr<Piece>>> grid;

    Board() : grid(SIZE, std::vector<std::shared_ptr<Piece>>(SIZE, nullptr)) {}

    bool isValid(Position pos) const {
        return pos.row >= 0 && pos.row < SIZE && pos.col >= 0 && pos.col < SIZE;
    }

    std::shared_ptr<Piece> getPiece(Position pos) const {
        if (!isValid(pos)) return nullptr;
        return grid[pos.row][pos.col];
    }

    void setPiece(Position pos, std::shared_ptr<Piece> piece) {
        if (isValid(pos)) grid[pos.row][pos.col] = piece;
    }

    static bool isPathClear(Position start, Position end, const std::vector<std::vector<std::shared_ptr<Piece>>>& b) {
        int dRow = end.row - start.row;
        int dCol = end.col - start.col;
        int stepRow = (dRow == 0) ? 0 : (dRow > 0 ? 1 : -1);
        int stepCol = (dCol == 0) ? 0 : (dCol > 0 ? 1 : -1);

        int currRow = start.row + stepRow;
        int currCol = start.col + stepCol;
        while (currRow != end.row || currCol != end.col) {
            if (b[currRow][currCol] != nullptr) return false;
            currRow += stepRow;
            currCol += stepCol;
        }
        return true;
    }
};

class Rook : public Piece {
public:
    Rook(Color c) : Piece(c, PieceType::ROOK) {}
    bool canMove(Position s, Position e, const std::vector<std::vector<std::shared_ptr<Piece>>>& b) const override {
        if (s.row != e.row && s.col != e.col) return false;
        return Board::isPathClear(s, e, b);
    }
};

class Bishop : public Piece {
public:
    Bishop(Color c) : Piece(c, PieceType::BISHOP) {}
    bool canMove(Position s, Position e, const std::vector<std::vector<std::shared_ptr<Piece>>>& b) const override {
        if (std::abs(s.row - e.row) != std::abs(s.col - e.col)) return false;
        return Board::isPathClear(s, e, b);
    }
};

class Queen : public Piece {
public:
    Queen(Color c) : Piece(c, PieceType::QUEEN) {}
    bool canMove(Position s, Position e, const std::vector<std::vector<std::shared_ptr<Piece>>>& b) const override {
        bool straight = (s.row == e.row || s.col == e.col);
        bool diagonal = (std::abs(s.row - e.row) == std::abs(s.col - e.col));
        if (!straight && !diagonal) return false;
        return Board::isPathClear(s, e, b);
    }
};

class Knight : public Piece {
public:
    Knight(Color c) : Piece(c, PieceType::KNIGHT) {}
    bool canMove(Position s, Position e, const std::vector<std::vector<std::shared_ptr<Piece>>>&) const override {
        int dR = std::abs(s.row - e.row);
        int dC = std::abs(s.col - e.col);
        return (dR == 1 && dC == 2) || (dR == 2 && dC == 1);
    }
};

class King : public Piece {
public:
    King(Color c) : Piece(c, PieceType::KING) {}
    bool canMove(Position s, Position e, const std::vector<std::vector<std::shared_ptr<Piece>>>&) const override {
        int dR = std::abs(s.row - e.row);
        int dC = std::abs(s.col - e.col);
        return dR <= 1 && dC <= 1;
    }
};

class Pawn : public Piece {
public:
    Pawn(Color c) : Piece(c, PieceType::PAWN) {}
    bool canMove(Position s, Position e, const std::vector<std::vector<std::shared_ptr<Piece>>>& b) const override {
        int dir = (color == Color::WHITE) ? 1 : -1;
        int startRow = (color == Color::WHITE) ? 1 : 6;

        // Standard 1 square advance
        if (e.col == s.col && e.row == s.row + dir && b[e.row][e.col] == nullptr) {
            return true;
        }
        // Initial 2 square jump
        if (e.col == s.col && s.row == startRow && e.row == s.row + 2 * dir &&
            b[s.row + dir][s.col] == nullptr && b[e.row][e.col] == nullptr) {
            return true;
        }
        // Diagonal capture
        if (std::abs(e.col - s.col) == 1 && e.row == s.row + dir && b[e.row][e.col] != nullptr) {
            return b[e.row][e.col]->getColor() != color;
        }
        return false;
    }
};

struct MoveRecord {
    Position from;
    Position to;
    std::shared_ptr<Piece> movedPiece;
    std::shared_ptr<Piece> capturedPiece;
};

class ChessGame {
private:
    Board board;
    Color currentTurn = Color::WHITE;
    std::stack<MoveRecord> history;

    Position findKing(Color color) const {
        for (int r = 0; r < Board::SIZE; ++r) {
            for (int c = 0; c < Board::SIZE; ++c) {
                auto p = board.grid[r][c];
                if (p && p->getType() == PieceType::KING && p->getColor() == color) {
                    return {r, c};
                }
            }
        }
        return {-1, -1};
    }

public:
    ChessGame() {
        setupBoard();
    }

    void setupBoard() {
        // White pieces
        board.setPiece({0, 0}, std::make_shared<Rook>(Color::WHITE));
        board.setPiece({0, 1}, std::make_shared<Knight>(Color::WHITE));
        board.setPiece({0, 2}, std::make_shared<Bishop>(Color::WHITE));
        board.setPiece({0, 3}, std::make_shared<Queen>(Color::WHITE));
        board.setPiece({0, 4}, std::make_shared<King>(Color::WHITE));
        board.setPiece({0, 5}, std::make_shared<Bishop>(Color::WHITE));
        board.setPiece({0, 6}, std::make_shared<Knight>(Color::WHITE));
        board.setPiece({0, 7}, std::make_shared<Rook>(Color::WHITE));
        for (int i = 0; i < 8; ++i) board.setPiece({1, i}, std::make_shared<Pawn>(Color::WHITE));

        // Black pieces
        board.setPiece({7, 0}, std::make_shared<Rook>(Color::BLACK));
        board.setPiece({7, 1}, std::make_shared<Knight>(Color::BLACK));
        board.setPiece({7, 2}, std::make_shared<Bishop>(Color::BLACK));
        board.setPiece({7, 3}, std::make_shared<Queen>(Color::BLACK));
        board.setPiece({7, 4}, std::make_shared<King>(Color::BLACK));
        board.setPiece({7, 5}, std::make_shared<Bishop>(Color::BLACK));
        board.setPiece({7, 6}, std::make_shared<Knight>(Color::BLACK));
        board.setPiece({7, 7}, std::make_shared<Rook>(Color::BLACK));
        for (int i = 0; i < 8; ++i) board.setPiece({6, i}, std::make_shared<Pawn>(Color::BLACK));
    }

    bool isUnderCheck(Color color) const {
        Position kingPos = findKing(color);
        if (kingPos.row == -1) return false;

        Color opp = (color == Color::WHITE) ? Color::BLACK : Color::WHITE;
        for (int r = 0; r < Board::SIZE; ++r) {
            for (int c = 0; c < Board::SIZE; ++c) {
                auto p = board.grid[r][c];
                if (p && p->getColor() == opp) {
                    if (p->canMove({r, c}, kingPos, board.grid)) return true;
                }
            }
        }
        return false;
    }

    bool makeMove(Position from, Position to) {
        auto piece = board.getPiece(from);
        if (!piece || piece->getColor() != currentTurn) {
            std::cout << "Invalid piece selection or not your turn!\n";
            return false;
        }

        auto destPiece = board.getPiece(to);
        if (destPiece && destPiece->getColor() == currentTurn) {
            std::cout << "Cannot capture your own piece!\n";
            return false;
        }

        if (!piece->canMove(from, to, board.grid)) {
            std::cout << "Illegal move path for piece!\n";
            return false;
        }

        // Apply Move tentatively
        board.setPiece(to, piece);
        board.setPiece(from, nullptr);

        // Disallow move if it leaves player's own king in check
        if (isUnderCheck(currentTurn)) {
            // Rollback
            board.setPiece(from, piece);
            board.setPiece(to, destPiece);
            std::cout << "Illegal move: Your King is in check!\n";
            return false;
        }

        history.push({from, to, piece, destPiece});
        currentTurn = (currentTurn == Color::WHITE) ? Color::BLACK : Color::WHITE;

        std::cout << "Move successful! Next turn: "
                  << (currentTurn == Color::WHITE ? "WHITE" : "BLACK") << "\n";
        return true;
    }

    void undo() {
        if (history.empty()) {
            std::cout << "No moves to undo!\n";
            return;
        }
        auto record = history.top();
        history.pop();

        board.setPiece(record.from, record.movedPiece);
        board.setPiece(record.to, record.capturedPiece);
        currentTurn = (currentTurn == Color::WHITE) ? Color::BLACK : Color::WHITE;
        std::cout << "Move undone!\n";
    }
};

int main() {
    ChessGame game;
    std::cout << "--- Playing Move 1: e2 to e4 (White Pawn) ---\n";
    game.makeMove({1, 4}, {3, 4});

    std::cout << "--- Playing Move 2: e7 to e5 (Black Pawn) ---\n";
    game.makeMove({6, 4}, {4, 4});

    std::cout << "--- Undoing Last Move ---\n";
    game.undo();
    return 0;
}

#include <iostream>
