#include <unordered_map>
#include <unordered_set>
#include <memory>

enum class ChannelType { EMAIL, SMS, PUSH, WHATSAPP };
enum class NotificationPriority { LOW, MEDIUM, HIGH, URGENT };

struct NotificationPayload {
    std::string recipientId;
    std::string title;
    std::string message;
    NotificationPriority priority;
};

// 1. STRATEGY PATTERN: Senders for each channel
class NotificationSender {
public:
    virtual ~NotificationSender() = default;
    virtual bool send(const NotificationPayload& payload) = 0;
    virtual ChannelType getChannelType() const = 0;
};

class EmailSender : public NotificationSender {
public:
    bool send(const NotificationPayload& payload) override {
        std::cout << "[EMAIL DISPATCHED] To: " << payload.recipientId
                  << " | Title: " << payload.title
                  << " | Body: " << payload.message << "\n";
        return true;
    }
    ChannelType getChannelType() const override { return ChannelType::EMAIL; }
};

class SMSSender : public NotificationSender {
public:
    bool send(const NotificationPayload& payload) override {
        std::cout << "[SMS DISPATCHED] To: " << payload.recipientId
                  << " | Text: " << payload.message << "\n";
        return true;
    }
    ChannelType getChannelType() const override { return ChannelType::SMS; }
};

class PushSender : public NotificationSender {
public:
    bool send(const NotificationPayload& payload) override {
        std::cout << "[PUSH NOTIFICATION] Device User: " << payload.recipientId
                  << " | Header: " << payload.title << "\n";
        return true;
    }
    ChannelType getChannelType() const override { return ChannelType::PUSH; }
};

// 2. FACTORY / REGISTRY PATTERN: Dynamically resolves channel senders
class NotificationSenderFactory {
private:
    std::unordered_map<ChannelType, std::shared_ptr<NotificationSender>> senders;

public:
    void registerSender(std::shared_ptr<NotificationSender> sender) {
        senders[sender->getChannelType()] = sender;
    }

    std::shared_ptr<NotificationSender> getSender(ChannelType type) const {
        auto it = senders.find(type);
        if (it != senders.end()) return it->second;
        return nullptr;
    }
};

// 3. USER PREFERENCES
class UserProfile {
private:
    std::string userId;
    std::string email;
    std::string phone;
    std::unordered_set<ChannelType> preferredChannels;

public:
    UserProfile(std::string id, std::string em, std::string ph)
        : userId(id), email(em), phone(ph) {}

    std::string getId() const { return userId; }

    void enableChannel(ChannelType type) { preferredChannels.insert(type); }
    void disableChannel(ChannelType type) { preferredChannels.erase(type); }

    const std::unordered_set<ChannelType>& getPreferences() const {
        return preferredChannels;
    }
};

// 4. OBSERVER PATTERN: Listens to domain events and dispatches notifications
class NotificationService {
private:
    NotificationSenderFactory factory;
    std::unordered_map<std::string, std::shared_ptr<UserProfile>> users;

public:
    void registerUser(std::shared_ptr<UserProfile> user) {
        users[user->getId()] = user;
    }

    void registerSender(std::shared_ptr<NotificationSender> sender) {
        factory.registerSender(sender);
    }

    void sendNotification(const NotificationPayload& payload) {
        auto it = users.find(payload.recipientId);
        if (it == users.end()) {
            std::cout << "User: " << payload.recipientId << " not found!\n";
            return;
        }

        auto user = it->second;
        const auto& channels = user->getPreferences();

        if (channels.empty()) {
            std::cout << "No channels enabled for user: " << user->getId() << ". Skipped.\n";
            return;
        }

        for (const auto& channel : channels) {
            auto sender = factory.getSender(channel);
            if (sender) {
                sender->send(payload);
            } else {
                std::cout << "Warning: Channel handler not registered!\n";
            }
        }
    }
};

int main() {
    NotificationService service;

    // Register supported senders
    service.registerSender(std::make_shared<EmailSender>());
    service.registerSender(std::make_shared<SMSSender>());
    service.registerSender(std::make_shared<PushSender>());

    // Configure user profiles with channel opt-ins
    auto user1 = std::make_shared<UserProfile>("USR_101", "alice@test.com", "+91-9876543210");
    user1->enableChannel(ChannelType::EMAIL);
    user1->enableChannel(ChannelType::PUSH);
    service.registerUser(user1);

    auto user2 = std::make_shared<UserProfile>("USR_102", "bob@test.com", "+91-9123456780");
    user2->enableChannel(ChannelType::SMS);
    service.registerUser(user2);

    std::cout << "--- Scenario 1: Notifying User 1 (Email + Push) ---\n";
    NotificationPayload p1{"USR_101", "Order Shipped", "Your package is on its way!", NotificationPriority::HIGH};
    service.sendNotification(p1);

    std::cout << "\n--- Scenario 2: Notifying User 2 (SMS Only) ---\n";
    NotificationPayload p2{"USR_102", "OTP Alert", "Your secret login OTP is 9482.", NotificationPriority::URGENT};
    service.sendNotification(p2);

    return 0;
}

#include <iostream>
