enum class LogLevel { DEBUG = 1, INFO = 2, WARN = 3, ERROR = 4 };

class LogSink {
protected:
    LogLevel sinkThreshold;
    std::shared_ptr<LogSink> nextSink;
    mutable std::mutex sinkMutex;

    virtual void writeRecord(LogLevel level, const std::string& message) = 0;

public:
    explicit LogSink(LogLevel threshold) : sinkThreshold(threshold), nextSink(nullptr) {}
    virtual ~LogSink() = default;

    void setNext(std::shared_ptr<LogSink> next) {
        nextSink = next;
    }

    void handleLog(LogLevel level, const std::string& message) {
        if (level >= sinkThreshold) {
            std::lock_guard<std::mutex> lock(sinkMutex);
            writeRecord(level, message);
        }
        if (nextSink) {
            nextSink->handleLog(level, message);
        }
    }
};

class ConsoleLogSink : public LogSink {
public:
    explicit ConsoleLogSink(LogLevel threshold) : LogSink(threshold) {}
protected:
    void writeRecord(LogLevel, const std::string& message) override {
        std::cout << "[CONSOLE_SINK] " << message << "\n";
    }
};

class FileLogSink : public LogSink {
public:
    explicit FileLogSink(LogLevel threshold) : LogSink(threshold) {}
protected:
    void writeRecord(LogLevel, const std::string& message) override {
        std::cout << "[FILE_SINK >> app.log] " << message << "\n";
    }
};

class DatabaseLogSink : public LogSink {
public:
    explicit DatabaseLogSink(LogLevel threshold) : LogSink(threshold) {}
protected:
    void writeRecord(LogLevel, const std::string& message) override {
        std::cout << "[DB_SINK >> INSERT INTO logs] " << message << "\n";
    }
};

// SINGLETON THREAD-SAFE LOGGER MANAGER
class Logger {
private:
    std::shared_ptr<LogSink> chainRoot;
    static std::shared_ptr<Logger> instance;
    static std::mutex instanceMutex;

    Logger() {
        // Build Default Chain:
        // Console Sink handles INFO and above
        // File Sink handles WARN and above
        // Database Sink handles ERROR and above exclusively
        auto console = std::make_shared<ConsoleLogSink>(LogLevel::INFO);
        auto file = std::make_shared<FileLogSink>(LogLevel::WARN);
        auto db = std::make_shared<DatabaseLogSink>(LogLevel::ERROR);

        console->setNext(file);
        file->setNext(db);
        chainRoot = console;
    }

    std::string formatLog(LogLevel level, const std::string& msg) const {
        std::string lvlStr = "INFO";
        if (level == LogLevel::DEBUG) lvlStr = "DEBUG";
        else if (level == LogLevel::WARN) lvlStr = "WARN";
        else if (level == LogLevel::ERROR) lvlStr = "ERROR";

        auto now = std::chrono::system_clock::now();
        auto timeT = std::chrono::system_clock::to_time_t(now);

        return "[" + lvlStr + "] " + msg;
    }

public:
    Logger(const Logger&) = delete;
    Logger& operator=(const Logger&) = delete;

    static std::shared_ptr<Logger> getInstance() {
        if (!instance) {
            std::lock_guard<std::mutex> lock(instanceMutex);
            if (!instance) {
                instance = std::shared_ptr<Logger>(new Logger());
            }
        }
        return instance;
    }

    void log(LogLevel level, const std::string& message) {
        if (chainRoot) {
            chainRoot->handleLog(level, formatLog(level, message));
        }
    }

    void debug(const std::string& msg) { log(LogLevel::DEBUG, msg); }
    void info(const std::string& msg)  { log(LogLevel::INFO, msg); }
    void warn(const std::string& msg)  { log(LogLevel::WARN, msg); }
    void error(const std::string& msg) { log(LogLevel::ERROR, msg); }
};

std::shared_ptr<Logger> Logger::instance = nullptr;
std::mutex Logger::instanceMutex;

int main() {
    auto logger = Logger::getInstance();

    std::cout << "--- 1. Testing DEBUG log (Filtered out by Console/File/DB) ---\n";
    logger->debug("Memory pointer initialized at 0x7ffd9");

    std::cout << "\n--- 2. Testing INFO log (Only Console receives it) ---\n";
    logger->info("Server listening on port 8080");

    std::cout << "\n--- 3. Testing WARN log (Console and File receive it) ---\n";
    logger->warn("High memory consumption threshold reached (> 85%)");

    std::cout << "\n--- 4. Testing ERROR log (Console, File, and DB receive it) ---\n";
    logger->error("Database connection pool exhausted! Requests dropped.");

    return 0;
}

#include <iostream>
#include <string>
#include <unordered_map>
#include <memory>
#include <mutex>
#include <chrono>
#include <deque>

class RateLimitingStrategy {
public:
    virtual ~RateLimitingStrategy() = default;
    virtual bool allowRequest(const std::string& clientId) = 0;
};

// 1. STRATEGY A: TOKEN BUCKET ALGORITHM
class TokenBucketStrategy : public RateLimitingStrategy {
private:
    struct Bucket {
        double tokens;
        std::chrono::steady_clock::time_point lastRefillTime;
    };

    int maxTokens;
    double refillRatePerSecond;
    std::unordered_map<std::string, Bucket> clientBuckets;
    std::mutex mtx;

public:
    TokenBucketStrategy(int capacity, double refillRate)
        : maxTokens(capacity), refillRatePerSecond(refillRate) {}

    bool allowRequest(const std::string& clientId) override {
        std::lock_guard<std::mutex> lock(mtx);
        auto now = std::chrono::steady_clock::now();

        auto it = clientBuckets.find(clientId);
        if (it == clientBuckets.end()) {
            clientBuckets[clientId] = {static_cast<double>(maxTokens) - 1.0, now};
            return true;
        }

        auto& bucket = it->second;
        auto elapsedSec = std::chrono::duration<double>(now - bucket.lastRefillTime).count();
        bucket.tokens = std::min(static_cast<double>(maxTokens), bucket.tokens + elapsedSec * refillRatePerSecond);
        bucket.lastRefillTime = now;

        if (bucket.tokens >= 1.0) {
            bucket.tokens -= 1.0;
            return true;
        }
        return false;
    }
};

// 2. STRATEGY B: SLIDING WINDOW LOG ALGORITHM
class SlidingWindowLogStrategy : public RateLimitingStrategy {
private:
    int maxRequests;
    std::chrono::milliseconds windowSize;
    std::unordered_map<std::string, std::deque<std::chrono::steady_clock::time_point>> requestLogs;
    std::mutex mtx;

public:
    SlidingWindowLogStrategy(int maxReq, std::chrono::milliseconds window)
        : maxRequests(maxReq), windowSize(window) {}

    bool allowRequest(const std::string& clientId) override {
        std::lock_guard<std::mutex> lock(mtx);
        auto now = std::chrono::steady_clock::now();
        auto& windowDeque = requestLogs[clientId];

        // Purge expired timestamps
        while (!windowDeque.empty() && (now - windowDeque.front() > windowSize)) {
            windowDeque.pop_front();
        }

        if (windowDeque.size() < static_cast<size_t>(maxRequests)) {
            windowDeque.push_back(now);
            return true;
        }
        return false;
    }
};

// 3. CONTEXT / SERVICE WRAPPER
class RateLimiterService {
private:
    std::shared_ptr<RateLimitingStrategy> strategy;

public:
    explicit RateLimiterService(std::shared_ptr<RateLimitingStrategy> initialStrategy)
        : strategy(initialStrategy) {}

    void setStrategy(std::shared_ptr<RateLimitingStrategy> newStrategy) {
        strategy = newStrategy;
    }

    bool isAllowed(const std::string& clientId) {
        return strategy->allowRequest(clientId);
    }
};

int main() {
    // Setup Token Bucket: Max 3 tokens, refills 1 token every second
    auto tokenBucket = std::make_shared<TokenBucketStrategy>(3, 1.0);
    RateLimiterService limiter(tokenBucket);

    std::string user = "user_101";
    std::cout << "--- Token Bucket Evaluation ---\n";
    for (int i = 1; i <= 5; ++i) {
        bool allowed = limiter.isAllowed(user);
        std::cout << "Request " << i << ": " << (allowed ? "ALLOWED (200 OK)" : "DENIED (429 Too Many Requests)") << "\n";
    }

    std::cout << "\n--- Swapping to Sliding Window Log Strategy (Limit 2 req / 500ms) ---\n";
    auto slidingWindow = std::make_shared<SlidingWindowLogStrategy>(2, std::chrono::milliseconds(500));
    limiter.setStrategy(slidingWindow);

    std::cout << "Req 1: " << (limiter.isAllowed(user) ? "ALLOWED" : "DENIED") << "\n";
    std::cout << "Req 2: " << (limiter.isAllowed(user) ? "ALLOWED" : "DENIED") << "\n";
    std::cout << "Req 3: " << (limiter.isAllowed(user) ? "ALLOWED" : "DENIED") << "\n";

    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <memory>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <thread>

struct Message {
    int offset;
    std::string key;
    std::string payload;
};

class TopicPartition {
private:
    int partitionId;
    std::vector<Message> log;
    mutable std::mutex partitionMutex;
    std::condition_variable cv;

public:
    explicit TopicPartition(int id) : partitionId(id) {}

    int append(const std::string& key, const std::string& payload) {
        std::lock_guard<std::mutex> lock(partitionMutex);
        int assignedOffset = static_cast<int>(log.size());
        log.push_back({assignedOffset, key, payload});
        cv.notify_all();
        return assignedOffset;
    }

    bool read(int offset, Message& outMsg) {
        std::unique_lock<std::mutex> lock(partitionMutex);
        if (offset < static_cast<int>(log.size())) {
            outMsg = log[offset];
            return true;
        }
        return false;
    }

    int getLatestOffset() const {
        std::lock_guard<std::mutex> lock(partitionMutex);
        return static_cast<int>(log.size());
    }
};

class Topic {
private:
    std::string name;
    std::vector<std::shared_ptr<TopicPartition>> partitions;

public:
    Topic(std::string tName, int numPartitions) : name(tName) {
        for (int i = 0; i < numPartitions; ++i) {
            partitions.push_back(std::make_shared<TopicPartition>(i));
        }
    }

    std::string getName() const { return name; }

    void publish(const std::string& key, const std::string& payload) {
        // Hash partition key to select target partition
        size_t partIndex = std::hash<std::string>{}(key) % partitions.size();
        int offset = partitions[partIndex]->append(key, payload);
        std::cout << "[Topic: " << name << " | Partition: " << partIndex 
                  << "] Published Msg: '" << payload << "' at Offset: " << offset << "\n";
    }

    std::shared_ptr<TopicPartition> getPartition(int index) {
        return partitions[index % partitions.size()];
    }

    int getPartitionCount() const { return static_cast<int>(partitions.size()); }
};

class ConsumerGroup {
private:
    std::string groupId;
    std::shared_ptr<Topic> topic;
    std::unordered_map<int, int> partitionOffsets; // PartitionId -> CommittedOffset
    std::mutex offsetMutex;

public:
    ConsumerGroup(std::string id, std::shared_ptr<Topic> top) : groupId(id), topic(top) {
        for (int i = 0; i < topic->getPartitionCount(); ++i) {
            partitionOffsets[i] = 0;
        }
    }

    void pollMessages(int partitionId) {
        auto partition = topic->getPartition(partitionId);
        int currentOffset = 0;
        {
            std::lock_guard<std::mutex> lock(offsetMutex);
            currentOffset = partitionOffsets[partitionId];
        }

        Message msg;
        while (partition->read(currentOffset, msg)) {
            std::cout << "[ConsumerGroup: " << groupId << "] Consumed Partition: " 
                      << partitionId << ", Offset: " << msg.offset 
                      << ", Data: " << msg.payload << "\n";
            currentOffset++;
        }

        {
            std::lock_guard<std::mutex> lock(offsetMutex);
            partitionOffsets[partitionId] = currentOffset;
        }
    }
};

int main() {
    // Create a topic with 2 partitions
    auto orderTopic = std::make_shared<Topic>("orders", 2);

    // Create two independent consumer groups
    auto billingGroup = std::make_shared<ConsumerGroup>("BillingService", orderTopic);
    auto notificationGroup = std::make_shared<ConsumerGroup>("NotificationService", orderTopic);

    std::cout << "--- 1. Publishing Events to Topic ---\n";
    orderTopic->publish("user_A", "Order #1001 Created");
    orderTopic->publish("user_B", "Order #1002 Created");
    orderTopic->publish("user_A", "Order #1003 Created");

    std::cout << "\n--- 2. Billing Group Consuming Partition 0 & 1 ---\n";
    billingGroup->pollMessages(0);
    billingGroup->pollMessages(1);

    std::cout << "\n--- 3. Notification Group Consuming (Independent Offset) ---\n";
    notificationGroup->pollMessages(0);
    notificationGroup->pollMessages(1);

    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <memory>
#include <stack>

// RECEIVER: Holds the raw text state
class TextDocument {
private:
    std::string content;

public:
    const std::string& getContent() const { return content; }

    void insert(size_t index, const std::string& text) {
        if (index > content.length()) index = content.length();
        content.insert(index, text);
    }

    void erase(size_t index, size_t length) {
        if (index >= content.length()) return;
        content.erase(index, length);
    }
};

// COMMAND INTERFACE
class Command {
public:
    virtual ~Command() = default;
    virtual void execute() = 0;
    virtual void undo() = 0;
};

// CONCRETE COMMAND: INSERT
class InsertCommand : public Command {
private:
    TextDocument& doc;
    size_t index;
    std::string textInserted;

public:
    InsertCommand(TextDocument& d, size_t idx, std::string text)
        : doc(d), index(idx), textInserted(std::move(text)) {}

    void execute() override {
        doc.insert(index, textInserted);
    }

    void undo() override {
        doc.erase(index, textInserted.length());
    }
};

// CONCRETE COMMAND: DELETE
class DeleteCommand : public Command {
private:
    TextDocument& doc;
    size_t index;
    size_t length;
    std::string deletedTextSnapshot; // Memento snapshot of deleted text

public:
    DeleteCommand(TextDocument& d, size_t idx, size_t len)
        : doc(d), index(idx), length(len) {}

    void execute() override {
        const std::string& current = doc.getContent();
        if (index < current.length()) {
            deletedTextSnapshot = current.substr(index, length);
            doc.erase(index, length);
        }
    }

    void undo() override {
        if (!deletedTextSnapshot.empty()) {
            doc.insert(index, deletedTextSnapshot);
        }
    }
};

// INVOKER: Manages execution, undo and redo stacks
class TextEditor {
private:
    TextDocument doc;
    std::stack<std::shared_ptr<Command>> undoStack;
    std::stack<std::shared_ptr<Command>> redoStack;

public:
    void executeCommand(std::shared_ptr<Command> cmd) {
        cmd->execute();
        undoStack.push(cmd);
        // Any new action invalidates current redo tree
        while (!redoStack.empty()) redoStack.pop();
    }

    void insert(size_t index, const std::string& text) {
        executeCommand(std::make_shared<InsertCommand>(doc, index, text));
    }

    void erase(size_t index, size_t length) {
        executeCommand(std::make_shared<DeleteCommand>(doc, index, length));
    }

    void undo() {
        if (undoStack.empty()) {
            std::cout << "Nothing to undo!\n";
            return;
        }
        auto cmd = undoStack.top();
        undoStack.pop();
        cmd->undo();
        redoStack.push(cmd);
    }

    void redo() {
        if (redoStack.empty()) {
            std::cout << "Nothing to redo!\n";
            return;
        }
        auto cmd = redoStack.top();
        redoStack.pop();
        cmd->execute();
        undoStack.push(cmd);
    }

    void printDocument() const {
        std::cout << "Current Document: \"" << doc.getContent() << "\"\n";
    }
};

int main() {
    TextEditor editor;

    std::cout << "--- Step 1: Type 'Hello World' ---\n";
    editor.insert(0, "Hello World");
    editor.printDocument();

    std::cout << "\n--- Step 2: Append ' in C++' ---\n";
    editor.insert(11, " in C++");
    editor.printDocument();

    std::cout << "\n--- Step 3: Undo Last Insert ---\n";
    editor.undo();
    editor.printDocument();

    std::cout << "\n--- Step 4: Redo Last Insert ---\n";
    editor.redo();
    editor.printDocument();

    std::cout << "\n--- Step 5: Delete 'World' ---\n";
    editor.erase(6, 5);
    editor.printDocument();

    std::cout << "\n--- Step 6: Undo Delete ---\n";
    editor.undo();
    editor.printDocument();

    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <memory>
#include <cmath>

struct Location {
    double x;
    double y;
    double distanceTo(const Location& other) const {
        return std::sqrt(std::pow(x - other.x, 2) + std::pow(y - other.y, 2));
    }
};

struct MenuItem {
    std::string id;
    std::string name;
    double price;
};

struct DeliveryPartner {
    std::string id;
    std::string name;
    Location location;
    bool isAvailable = true;
};

class Order; // Forward declaration

// OBSERVER PATTERN: Status change listener
class OrderObserver {
public:
    virtual ~OrderObserver() = default;
    virtual void onStatusChanged(const std::string& orderId, const std::string& newStatus) = 0;
};

class CustomerAppNotifier : public OrderObserver {
private:
    std::string customerName;
public:
    explicit CustomerAppNotifier(std::string name) : customerName(std::move(name)) {}
    void onStatusChanged(const std::string& orderId, const std::string& newStatus) override {
        std::cout << "[APP NOTIFICATION to " << customerName << "]: Order "
                  << orderId << " status updated to -> " << newStatus << "\n";
    }
};

// STATE PATTERN: Order Lifecycle
class OrderState {
public:
    virtual ~OrderState() = default;
    virtual void next(Order& order) = 0;
    virtual std::string getStatusName() const = 0;
};

class DeliveredState : public OrderState {
public:
    void next(Order&) override {
        std::cout << "Order is already delivered. Terminal state reached.\n";
    }
    std::string getStatusName() const override { return "DELIVERED"; }
};

class OutForDeliveryState : public OrderState {
public:
    void next(Order& order) override;
    std::string getStatusName() const override { return "OUT_FOR_DELIVERY"; }
};

class PreparingState : public OrderState {
public:
    void next(Order& order) override;
    std::string getStatusName() const override { return "PREPARING"; }
};

class PlacedState : public OrderState {
public:
    void next(Order& order) override;
    std::string getStatusName() const override { return "PLACED"; }
};

class Order {
private:
    std::string orderId;
    std::string restaurantId;
    std::shared_ptr<DeliveryPartner> assignedPartner;
    std::shared_ptr<OrderState> currentState;
    std::vector<std::shared_ptr<OrderObserver>> observers;

public:
    Order(std::string id, std::string restId)
        : orderId(std::move(id)), restaurantId(std::move(restId)) {
        currentState = std::make_shared<PlacedState>();
    }

    std::string getId() const { return orderId; }
    std::string getRestaurantId() const { return restaurantId; }

    void setPartner(std::shared_ptr<DeliveryPartner> p) { assignedPartner = p; }
    std::shared_ptr<DeliveryPartner> getPartner() const { return assignedPartner; }

    void setState(std::shared_ptr<OrderState> state) {
        currentState = state;
        notifyObservers();
    }

    void addObserver(std::shared_ptr<OrderObserver> obs) {
        observers.push_back(obs);
    }

    void notifyObservers() {
        for (const auto& obs : observers) {
            obs->onStatusChanged(orderId, currentState->getStatusName());
        }
    }

    void advance() {
        currentState->next(*this);
    }
};

// State transitions implementation
void PlacedState::next(Order& order) {
    order.setState(std::make_shared<PreparingState>());
}

void PreparingState::next(Order& order) {
    order.setState(std::make_shared<OutForDeliveryState>());
}

void OutForDeliveryState::next(Order& order) {
    if (order.getPartner()) order.getPartner()->isAvailable = true;
    order.setState(std::make_shared<DeliveredState>());
}

// STRATEGY PATTERN: Delivery Partner Assignment
class PartnerMatchingStrategy {
public:
    virtual ~PartnerMatchingStrategy() = default;
    virtual std::shared_ptr<DeliveryPartner> findPartner(
        const Location& restaurantLocation,
        const std::vector<std::shared_ptr<DeliveryPartner>>& partners) = 0;
};

class NearestPartnerStrategy : public PartnerMatchingStrategy {
public:
    std::shared_ptr<DeliveryPartner> findPartner(
        const Location& restLoc,
        const std::vector<std::shared_ptr<DeliveryPartner>>& partners) override {
        std::shared_ptr<DeliveryPartner> closest = nullptr;
        double minDistance = 1e9;

        for (const auto& p : partners) {
            if (p->isAvailable) {
                double dist = p->location.distanceTo(restLoc);
                if (dist < minDistance) {
                    minDistance = dist;
                    closest = p;
                }
            }
        }
        return closest;
    }
};

int main() {
    // Setup Delivery Fleet
    std::vector<std::shared_ptr<DeliveryPartner>> fleet = {
        std::make_shared<DeliveryPartner>(DeliveryPartner{"Rider_1", "Deepak", {2.0, 3.0}, true}),
        std::make_shared<DeliveryPartner>(DeliveryPartner{"Rider_2", "Suresh", {12.0, 15.0}, true})
    };

    Location restaurantLocation{1.0, 2.0};
    auto matchingStrategy = std::make_shared<NearestPartnerStrategy>();

    // Customer creates and checks out order
    auto order = std::make_shared<Order>("ORD_9901", "BIRYANI_CENTRAL");
    auto customerNotification = std::make_shared<CustomerAppNotifier>("Ankit");
    order->addObserver(customerNotification);

    std::cout << "--- Step 1: Order Placed ---\n";
    // Matches nearest delivery driver
    auto assignedDriver = matchingStrategy->findPartner(restaurantLocation, fleet);
    if (assignedDriver) {
        assignedDriver->isAvailable = false;
        order->setPartner(assignedDriver);
        std::cout << "Assigned Driver: " << assignedDriver->name << " to Order.\n";
    }

    std::cout << "\n--- Step 2: Kitchen Begins Cooking ---\n";
    order->advance(); // Transitions to PREPARING

    std::cout << "\n--- Step 3: Driver Picked Up Order ---\n";
    order->advance(); // Transitions to OUT_FOR_DELIVERY

    std::cout << "\n--- Step 4: Driver Handed Over Food ---\n";
    order->advance(); // Transitions to DELIVERED

    return 0;
}

#include <iostream>
#include <unordered_map>
#include <shared_mutex>
#include <mutex>
#include <thread>
#include <chrono>
#include <optional>
#include <atomic>
#include <condition_variable>

template <typename K, typename V>
class ThreadSafeTTLCache {
private:
    struct CacheEntry {
        V value;
        std::chrono::steady_clock::time_point expiryTime;

        bool isExpired() const {
            return std::chrono::steady_clock::now() > expiryTime;
        }
    };

    std::unordered_map<K, CacheEntry> store;
    mutable std::shared_mutex rwMutex;
    std::condition_variable_any cv;
    std::atomic<bool> stopFlag{false};
    std::thread cleanerThread;

    void backgroundCleanupWorker(std::chrono::milliseconds interval) {
        while (!stopFlag) {
            {
                std::unique_lock<std::shared_mutex> lock(rwMutex);
                cv.wait_for(lock, interval, [this]() { return stopFlag.load(); });
                if (stopFlag) break;

                auto now = std::chrono::steady_clock::now();
                for (auto it = store.begin(); it != store.end(); ) {
                    if (now > it->second.expiryTime) {
                        std::cout << "[Active Cleanup] Evicted expired key.\n";
                        it = store.erase(it);
                    } else {
                        ++it;
                    }
                }
            }
        }
    }

public:
    explicit ThreadSafeTTLCache(std::chrono::milliseconds cleanupInterval = std::chrono::milliseconds(500))
        : cleanerThread(&ThreadSafeTTLCache::backgroundCleanupWorker, this, cleanupInterval) {}

    ~ThreadSafeTTLCache() {
        stopFlag = true;
        cv.notify_all();
        if (cleanerThread.joinable()) {
            cleanerThread.join();
        }
    }

    void put(const K& key, const V& value, std::chrono::milliseconds ttl) {
        std::unique_lock<std::shared_mutex> lock(rwMutex); // Exclusive Writer Lock
        auto exp = std::chrono::steady_clock::now() + ttl;
        store[key] = CacheEntry{value, exp};
    }

    std::optional<V> get(const K& key) {
        // Step 1: Acquire Shared Reader Lock for fast concurrent reads
        {
            std::shared_lock<std::shared_mutex> readerLock(rwMutex);
            auto it = store.find(key);
            if (it == store.end()) return std::nullopt;
            if (!it->second.isExpired()) {
                return it->second.value;
            }
        }

        // Step 2: Lazy/Passive eviction if expired
        std::unique_lock<std::shared_mutex> writerLock(rwMutex);
        auto it = store.find(key);
        if (it != store.end() && it->second.isExpired()) {
            store.erase(it);
            return std::nullopt;
        }
        return (it != store.end()) ? std::optional<V>(it->second.value) : std::nullopt;
    }

    size_t size() const {
        std::shared_lock<std::shared_mutex> lock(rwMutex);
        return store.size();
    }
};

int main() {
    ThreadSafeTTLCache<std::string, std::string> cache(std::chrono::milliseconds(300));

    cache.put("session_1", "user_alpha", std::chrono::milliseconds(200));
    cache.put("session_2", "user_beta", std::chrono::milliseconds(800));

    std::cout << "Initial get session_1: " << cache.get("session_1").value_or("None") << "\n";

    // Sleep past session_1 TTL
    std::this_thread::sleep_for(std::chrono::milliseconds(400));

    std::cout << "After 400ms get session_1 (Passive/Active check): " 
              << cache.get("session_1").value_or("EXPIRED") << "\n";
    std::cout << "After 400ms get session_2 (Should exist): " 
              << cache.get("session_2").value_or("EXPIRED") << "\n";

    return 0;
}

#include <iostream>
#include <queue>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <functional>
#include <memory>
#include <atomic>

struct Task {
    int taskId;
    std::string name;
    std::chrono::steady_clock::time_point executionTime;
    int priority; // Higher value = higher priority
    std::chrono::milliseconds repeatInterval; // 0 if one-off
    std::function<void()> action;

    bool operator>(const Task& other) const {
        if (executionTime == other.executionTime) {
            return priority < other.priority; // higher priority executes first
        }
        return executionTime > other.executionTime; // min-heap by time
    }
};

class TaskScheduler {
private:
    std::priority_queue<Task, std::vector<Task>, std::greater<Task>> taskQueue;
    std::mutex queueMutex;
    std::condition_variable cv;
    std::vector<std::thread> workers;
    std::atomic<bool> stopFlag{false};
    std::atomic<int> taskIdCounter{1};

    void workerLoop() {
        while (true) {
            Task currentTask;
            {
                std::unique_lock<std::mutex> lock(queueMutex);

                while (!stopFlag && taskQueue.empty()) {
                    cv.wait(lock);
                }

                if (stopFlag && taskQueue.empty()) return;

                auto now = std::chrono::steady_clock::now();
                if (taskQueue.top().executionTime > now) {
                    cv.wait_until(lock, taskQueue.top().executionTime);
                    if (stopFlag && taskQueue.empty()) return;
                    if (taskQueue.empty() || taskQueue.top().executionTime > std::chrono::steady_clock::now()) {
                        continue;
                    }
                }

                currentTask = taskQueue.top();
                taskQueue.pop();
            }

            // Execute Task outside the lock to keep queue open for other workers
            if (currentTask.action) {
                currentTask.action();
            }

            // Reschedule if recurring
            if (currentTask.repeatInterval.count() > 0 && !stopFlag) {
                std::lock_guard<std::mutex> lock(queueMutex);
                currentTask.executionTime = std::chrono::steady_clock::now() + currentTask.repeatInterval;
                taskQueue.push(currentTask);
                cv.notify_all();
            }
        }
    }

public:
    explicit TaskScheduler(size_t numWorkers = 2) {
        for (size_t i = 0; i < numWorkers; ++i) {
            workers.emplace_back(&TaskScheduler::workerLoop, this);
        }
    }

    ~TaskScheduler() {
        stopFlag = true;
        cv.notify_all();
        for (auto& w : workers) {
            if (w.joinable()) w.join();
        }
    }

    int schedule(const std::string& name, std::function<void()> action, 
                 std::chrono::milliseconds delay, int priority = 0, 
                 std::chrono::milliseconds interval = std::chrono::milliseconds(0)) {
        int id = taskIdCounter++;
        auto execTime = std::chrono::steady_clock::now() + delay;
        Task t{id, name, execTime, priority, interval, action};

        {
            std::lock_guard<std::mutex> lock(queueMutex);
            taskQueue.push(t);
        }
        cv.notify_all();
        return id;
    }
};

int main() {
    TaskScheduler scheduler(3); // 3 worker threads

    std::cout << "--- Scheduling Tasks ---\n";

    // 1. One-off task with 1000ms delay
    scheduler.schedule("Task_A", []() {
        std::cout << "[Executed] Task A (Delayed 1000ms)\n";
    }, std::chrono::milliseconds(1000), 1);

    // 2. High priority task with 500ms delay
    scheduler.schedule("Task_B_HighPriority", []() {
        std::cout << "[Executed] Task B (High Priority, Delayed 500ms)\n";
    }, std::chrono::milliseconds(500), 10);

    // 3. Recurring task starting at 200ms, repeats every 400ms
    scheduler.schedule("Task_C_Recurring", []() {
        std::cout << "[Executed] Task C (Recurring Heartbeat)\n";
    }, std::chrono::milliseconds(200), 5, std::chrono::milliseconds(400));

    // Allow tasks to run for 1.5 seconds
    std::this_thread::sleep_for(std::chrono::milliseconds(1500));

    std::cout << "--- Shutting down Task Scheduler ---\n";
    return 0;
}

#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>
#include <memory>
#include <mutex>
#include <chrono>
#include <optional>

enum class TransactionStatus { SUCCESS, FAILED, ALREADY_PROCESSED };

struct TransactionRecord {
    std::string transactionId;
    std::string fromUser;
    std::string toUser;
    double amount;
    TransactionStatus status;
    std::string idempotencyKey;
    std::string timestamp;
};

class UserWallet {
public:
    std::string userId;
    double balance;
    std::mutex walletMutex;

    UserWallet(std::string id, double initialBalance = 0.0)
        : userId(std::move(id)), balance(initialBalance) {}
};

class PaymentWalletService {
private:
    std::unordered_map<std::string, std::shared_ptr<UserWallet>> wallets;
    std::unordered_map<std::string, TransactionRecord> idempotencyStore;
    std::vector<TransactionRecord> transactionHistory;
    std::mutex globalMutex;
    int txnCounter = 1000;

public:
    void registerUser(const std::string& userId, double initialBalance = 0.0) {
        std::lock_guard<std::mutex> lock(globalMutex);
        wallets[userId] = std::make_shared<UserWallet>(userId, initialBalance);
    }

    TransactionRecord transferFunds(const std::string& idempotencyKey,
                                  const std::string& fromUserId,
                                  const std::string& toUserId,
                                  double amount) {
        if (fromUserId == toUserId || amount <= 0.0) {
            return {"TXN_INVALID", fromUserId, toUserId, amount, TransactionStatus::FAILED, idempotencyKey, "NOW"};
        }

        std::shared_ptr<UserWallet> fromWallet, toWallet;
        {
            std::lock_guard<std::mutex> lock(globalMutex);
            // 1. Idempotency Check: Prevent duplicate payment processing
            auto it = idempotencyStore.find(idempotencyKey);
            if (it != idempotencyStore.end()) {
                std::cout << "[IDEMPOTENCY TRIGGERED] Request with key: " << idempotencyKey 
                          << " already processed. Returning cached receipt.\n";
                return it->second;
            }

            if (wallets.find(fromUserId) == wallets.end() || wallets.find(toUserId) == wallets.end()) {
                return {"TXN_FAILED", fromUserId, toUserId, amount, TransactionStatus::FAILED, idempotencyKey, "NOW"};
            }
            fromWallet = wallets[fromUserId];
            toWallet = wallets[toUserId];
        }

        // 2. Lock both user accounts simultaneously to prevent deadlock
        std::unique_lock<std::mutex> lockA(fromWallet->walletMutex, std::defer_lock);
        std::unique_lock<std::mutex> lockB(toWallet->walletMutex, std::defer_lock);
        std::lock(lockA, lockB);

        TransactionRecord record;
        {
            std::lock_guard<std::mutex> lock(globalMutex);
            record.transactionId = "TXN_" + std::to_string(++txnCounter);
            record.fromUser = fromUserId;
            record.toUser = toUserId;
            record.amount = amount;
            record.idempotencyKey = idempotencyKey;
            record.timestamp = "2026-10-02T12:00:00Z";

            if (fromWallet->balance < amount) {
                std::cout << "Transfer failed: Insufficient balance for user: " << fromUserId << "\n";
                record.status = TransactionStatus::FAILED;
            } else {
                fromWallet->balance -= amount;
                toWallet->balance += amount;
                record.status = TransactionStatus::SUCCESS;
                std::cout << "Successfully transferred Rs " << amount << " from " 
                          << fromUserId << " to " << toUserId << " [Txn: " << record.transactionId << "]\n";
            }

            // Store result in idempotency cache and audit log
            idempotencyStore[idempotencyKey] = record;
            transactionHistory.push_back(record);
        }
        return record;
    }

    double getBalance(const std::string& userId) {
        std::lock_guard<std::mutex> lock(globalMutex);
        if (wallets.find(userId) != wallets.end()) {
            std::lock_guard<std::mutex> uLock(wallets[userId]->walletMutex);
            return wallets[userId]->balance;
        }
        return 0.0;
    }
};

int main() {
    PaymentWalletService walletApp;
    walletApp.registerUser("user_A", 1000.0);
    walletApp.registerUser("user_B", 200.0);

    std::string idemKey1 = "IDEM_TOKEN_98765";

    std::cout << "--- Step 1: Normal Transfer Request ---\n";
    walletApp.transferFunds(idemKey1, "user_A", "user_B", 300.0);
    std::cout << "User A Balance: Rs " << walletApp.getBalance("user_A") << "\n";
    std::cout << "User B Balance: Rs " << walletApp.getBalance("user_B") << "\n";

    std::cout << "\n--- Step 2: Identical Network Retry (Same Idempotency-Key) ---\n";
    walletApp.transferFunds(idemKey1, "user_A", "user_B", 300.0);
    std::cout << "User A Balance (Unchanged): Rs " << walletApp.getBalance("user_A") << "\n";
    std::cout << "User B Balance (Unchanged): Rs " << walletApp.getBalance("user_B") << "\n";

    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <memory>
#include <cmath>

struct Location {
    double x;
    double y;
    double distanceTo(const Location& other) const {
        return std::sqrt(std::pow(x - other.x, 2) + std::pow(y - other.y, 2));
    }
};

class Driver {
public:
    std::string id;
    std::string name;
    Location location;
    bool isAvailable = true;
    std::vector<int> ratings;

    Driver(std::string dId, std::string dName, Location loc)
        : id(std::move(dId)), name(std::move(dName)), location(loc) {}

    double getAverageRating() const {
        if (ratings.empty()) return 5.0;
        double sum = 0;
        for (int r : ratings) sum += r;
        return sum / ratings.size();
    }
};

// STRATEGY PATTERN: Pricing
class PricingStrategy {
public:
    virtual ~PricingStrategy() = default;
    virtual double calculateFare(double distanceKm) = 0;
};

class StandardPricingStrategy : public PricingStrategy {
public:
    double calculateFare(double distanceKm) override {
        return 50.0 + (distanceKm * 12.0); // Rs 50 Base + Rs 12/km
    }
};

class SurgePricingStrategy : public PricingStrategy {
private:
    double surgeMultiplier;
public:
    explicit SurgePricingStrategy(double multiplier) : surgeMultiplier(multiplier) {}
    double calculateFare(double distanceKm) override {
        double baseFare = 50.0 + (distanceKm * 12.0);
        return baseFare * surgeMultiplier;
    }
};

// STATE PATTERN: Ride States
class Ride;

class RideState {
public:
    virtual ~RideState() = default;
    virtual void next(Ride& ride) = 0;
    virtual std::string getStateName() const = 0;
};

class CompletedState : public RideState {
public:
    void next(Ride&) override {
        std::cout << "Ride is already completed.\n";
    }
    std::string getStateName() const override { return "COMPLETED"; }
};

class OngoingState : public RideState {
public:
    void next(Ride& ride) override;
    std::string getStateName() const override { return "ONGOING"; }
};

class AcceptedState : public RideState {
public:
    void next(Ride& ride) override;
    std::string getStateName() const override { return "ACCEPTED"; }
};

class RequestedState : public RideState {
public:
    void next(Ride& ride) override;
    std::string getStateName() const override { return "REQUESTED"; }
};

class Ride {
private:
    std::string rideId;
    std::string riderId;
    Location pickup;
    Location dropoff;
    std::shared_ptr<Driver> assignedDriver;
    std::shared_ptr<RideState> currentState;
    double estimatedFare = 0.0;

public:
    Ride(std::string id, std::string rId, Location p, Location d)
        : rideId(std::move(id)), riderId(std::move(rId)), pickup(p), dropoff(d) {
        currentState = std::make_shared<RequestedState>();
    }

    std::string getId() const { return rideId; }
    Location getPickup() const { return pickup; }
    Location getDropoff() const { return dropoff; }
    std::shared_ptr<Driver> getDriver() const { return assignedDriver; }

    void setDriver(std::shared_ptr<Driver> d) { assignedDriver = d; }
    void setFare(double fare) { estimatedFare = fare; }
    double getFare() const { return estimatedFare; }

    void setState(std::shared_ptr<RideState> state) {
        currentState = state;
        std::cout << "[RIDE " << rideId << "] Status updated to: " << currentState->getStateName() << "\n";
    }

    void advance() {
        currentState->next(*this);
    }
};

void RequestedState::next(Ride& ride) {
    ride.setState(std::make_shared<AcceptedState>());
}

void AcceptedState::next(Ride& ride) {
    ride.setState(std::make_shared<OngoingState>());
}

void OngoingState::next(Ride& ride) {
    if (ride.getDriver()) ride.getDriver()->isAvailable = true;
    ride.setState(std::make_shared<CompletedState>());
}

class UberDispatchService {
private:
    std::vector<std::shared_ptr<Driver>> drivers;

public:
    void registerDriver(std::shared_ptr<Driver> d) {
        drivers.push_back(d);
    }

    std::shared_ptr<Driver> findNearestDriver(const Location& pickup) {
        std::shared_ptr<Driver> bestDriver = nullptr;
        double minDistance = 1e9;
        for (const auto& d : drivers) {
            if (d->isAvailable) {
                double dist = d->location.distanceTo(pickup);
                if (dist < minDistance) {
                    minDistance = dist;
                    bestDriver = d;
                }
            }
        }
        return bestDriver;
    }
};

int main() {
    UberDispatchService dispatch;
    dispatch.registerDriver(std::make_shared<Driver>("D1", "Ramesh", Location{1.0, 1.5}));
    dispatch.registerDriver(std::make_shared<Driver>("D2", "Vikas", Location{10.0, 12.0}));

    Location riderPickup{1.2, 1.8};
    Location riderDrop{6.0, 8.0};
    double tripDistance = riderPickup.distanceTo(riderDrop);

    auto ride = std::make_shared<Ride>("TRIP_501", "Rider_Akash", riderPickup, riderDrop);

    // 1. Calculate fare using Surge strategy
    SurgePricingStrategy surgePricing(1.5); // 1.5x surge
    ride->setFare(surgePricing.calculateFare(tripDistance));
    std::cout << "Trip Distance: " << tripDistance << " km | Estimated Fare: Rs " << ride->getFare() << "\n";

    // 2. Dispatch nearest driver
    auto matchedDriver = dispatch.findNearestDriver(riderPickup);
    if (matchedDriver) {
        matchedDriver->isAvailable = false;
        ride->setDriver(matchedDriver);
        std::cout << "Matched with Driver: " << matchedDriver->name << " (Avg Rating: " << matchedDriver->getAverageRating() << ")\n";
        ride->advance(); // REQUESTED -> ACCEPTED
    }

    ride->advance(); // ACCEPTED -> ONGOING
    ride->advance(); // ONGOING -> COMPLETED

    return 0;
}

#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>
#include <memory>
#include <mutex>
#include <algorithm>
#include <thread>

class UserNode {
public:
    std::string userId;
    std::unordered_map<std::string, double> balances; // otherUserId -> net amount (positive = owes me)
    std::mutex userMutex;

    explicit UserNode(std::string id) : userId(std::move(id)) {}
};

class ConcurrentSplitwise {
private:
    std::unordered_map<std::string, std::shared_ptr<UserNode>> userRegistry;
    std::mutex registryMutex;

public:
    void registerUser(const std::string& userId) {
        std::lock_guard<std::mutex> lock(registryMutex);
        if (userRegistry.find(userId) == userRegistry.end()) {
            userRegistry[userId] = std::make_shared<UserNode>(userId);
        }
    }

    // Thread-safe pairwise expense addition with deadlock prevention
    void addPairwiseExpense(const std::string& payerId, const std::string& borrowerId, double amount) {
        if (payerId == borrowerId || amount <= 0.0) return;

        std::shared_ptr<UserNode> userA, userB;
        {
            std::lock_guard<std::mutex> regLock(registryMutex);
            userA = userRegistry[payerId];
            userB = userRegistry[borrowerId];
        }
        if (!userA || !userB) return;

        // CRITICAL: Deadlock-free locking. std::lock avoids AB-BA deadlock
        std::unique_lock<std::mutex> lock1(userA->userMutex, std::defer_lock);
        std::unique_lock<std::mutex> lock2(userB->userMutex, std::defer_lock);
        std::lock(lock1, lock2);

        // userA is owed money (+amount), userB owes money (-amount)
        userA->balances[borrowerId] += amount;
        userB->balances[payerId] -= amount;

        std::cout << "[Concurrent Log] Added expense: " << borrowerId 
                  << " owes " << payerId << " Rs " << amount << "\n";
    }

    void showBalances(const std::string& userId) {
        std::shared_ptr<UserNode> user;
        {
            std::lock_guard<std::mutex> regLock(registryMutex);
            user = userRegistry[userId];
        }
        if (!user) return;

        std::lock_guard<std::mutex> lock(user->userMutex);
        std::cout << "--- Live Balances for " << userId << " ---\n";
        bool clean = true;
        for (const auto& [otherId, net] : user->balances) {
            if (std::abs(net) > 0.001) {
                clean = false;
                if (net > 0) {
                    std::cout << otherId << " owes " << userId << ": Rs " << net << "\n";
                } else {
                    std::cout << userId << " owes " << otherId << ": Rs " << -net << "\n";
                }
            }
        }
        if (clean) std::cout << "All debts settled!\n";
    }
};

int main() {
    ConcurrentSplitwise splitwise;
    splitwise.registerUser("Alice");
    splitwise.registerUser("Bob");
    splitwise.registerUser("Charlie");

    std::cout << "--- Running Concurrent Expenses from Multiple Threads ---\n";

    // Thread 1: Alice pays for Bob (Rs 200)
    std::thread t1([&]() {
        for (int i = 0; i < 5; ++i) {
            splitwise.addPairwiseExpense("Alice", "Bob", 40.0);
        }
    });

    // Thread 2: Bob pays for Alice (Rs 150) concurrently
    std::thread t2([&]() {
        for (int i = 0; i < 5; ++i) {
            splitwise.addPairwiseExpense("Bob", "Alice", 30.0);
        }
    });

    // Thread 3: Charlie pays for Bob (Rs 100)
    std::thread t3([&]() {
        splitwise.addPairwiseExpense("Charlie", "Bob", 100.0);
    });

    t1.join();
    t2.join();
    t3.join();

    std::cout << "\n--- Final Balance Ledger ---\n";
    splitwise.showBalances("Alice");
    splitwise.showBalances("Bob");

    return 0;
}
